'use strict';
const APP_VERSION='0.119';
let state;
// Plain-English reference; reading Help never changes the campaign.
let helpTopic='getting-started',helpQuery='';
const HELP_TOPICS=[
{"id": "personal-goals", "title": "Companion goals and finished achievements", "tags": "purpose quest ambition cookbook atlas grotto necklace tournament remedy spirit Merrin masterpiece", "view": "development", "sections": [["Where do I start?", "Recruit a named companion, open her profile and choose Quests. Overview and Talk show the same personal goal and its current progress. Every goal has a specific finished result. Across all 16 companions there are 65 work stages, with two responses at each decision."], ["How does the work proceed?", "Choose a response, then a work method. The named room must be restored. Ordinary work needs no minimum skill and takes three assigned phases, or two with a qualifying existing support. A trained method takes one phase. Both you and the companion must be home and free. Crowns and materials are paid once when work starts; protected material reserves are respected. Choose Advance to work. Talking does not pass time."], ["Can I pause or use magic?", "Set the quest aside to pause without losing paid work. Resume when both participants are available. A suitable prepared spell can shorten eligible work, with its own component cost. It cannot replace tournament bouts, independent demonstrations, voluntary agreements or other stages labelled as practical tests."], ["What counts as success?", "Each quest shows its exact success condition and concludes with a celebration. It awards 2 advancement to each participant once, records the finished work in the associated room and unlocks two follow-up questions. Friendship is sufficient. The goal stays complete; follow-up conversations do not grant repeat rewards."], ["What are the equipment and supply rewards?", "Zahra creates Emberline, a two-capacity steel sword bearing rank-one Measured force. Sabine recovers her fox-clasp necklace. Both items belong to their makers or owners and must be equipped normally. Velis’s completed route adds up to 2 free provisions each morning, limited by your pantry target. Tamsin unlocks her cookbook menu at the normal daily provision cost. Other achievements are persistent finished works, not unlisted combat bonuses."], ["How does Elowen’s kit work?", "Her five stages require one manticore spine, one wyvern venom crystal and one basilisk scale, plus the listed ordinary supplies. Completion gives one kit. Restock for 3 unreserved silver ivy and 1 binding thread at the infirmary, with a maximum of ten ready. During a manticore, wyvern or basilisk encounter, the field-kit First aid choice consumes one kit, restores up to 4 vitality to one party member and clears venom and stone stiffness. It uses a normal exchange with normal enemy retaliation. Retreat before that exchange refunds the unused kit."], ["What happens to earlier personal quests?", "Earlier completed work for Mira, Koharu and Merrin counts toward the overlapping stages. Finish an already accepted earlier quest first. Once the new goal starts, its overlapping old invitation is no longer offered. Other outings, hobbies, romantic scenes and saved memories remain available separately. Recruiting everyone with Cheats does not complete personal goals."], ["How does Merrin handle physical objects?", "She has no mass but can exert force by concentrating. Familiar actions such as turning pages become easy; heavy, precise or unfamiliar work takes attention and rest. Her visible clothes and bell are part of her manifested form. Books and other real objects remain physical. Her conversations explain the difference, and this does not bypass locks, injury rules or consent."]]},
{"id": "named-recruitment", "title": "Finding named companions", "tags": "Mira Tamsin Koharu Zahra Fenna Kaede Elowen Nyssara Sylva Velis Rhess Iona Aurelia Neris Sabine Merrin spirit chapel recruitment demo", "view": "localEncounters", "sections": [["Is Mira in a fresh campaign?", "Mira starts in the demonstration campaign. There is currently no ordinary recruitment quest for her in a fresh campaign. Cheats can add her. She is not a hidden reward for a later chapter."], ["Who can I meet nearby?", "Koharu is available through the neighbouring theatre workshop from the beginning. Complete the first hearth-ward study for Kaede and Elowen, return a fern-nursery discovery for Fenna, and bring home the Ridge cistern survey for Nyssara. Follow the named introduction and any rescue lead shown on the board; a visit still requires agreement and a suitable bed."], ["Where do Tamsin, Velis and Rhess enter?", "Tamsin’s introduction comes from the correspondence recovered by salvaging Hillfold Bindery. Velis enters through the Chapter 6 caravan rescue. Rhess enters through the Chapter 7 watchtower trail. Their subsequent conversations, accommodation and household invitations remain separate choices."], ["Which named companions need summoning?", "Iona, Aurelia and Neris are authored contacts in Summoning. Learn Courteous passage and complete the listed paid contact ritual. Restoring the conservatory reveals Zahra’s letter; Sylva also needs a fern-nursery discovery. Their letters establish an identity, but their meetings still use a summoning ritual."], ["How do I meet Sabine and Merrin?", "Sabine’s lead comes from the bindery notes; use the Quiet chamber, escort and care conversations, then release her before discussing a household invitation. Restore the chapel to discover Merrin. Finish her three-part conversation, discuss a trial visit and offer a private room. After arrival, she decides separately whether she wants to stay."], ["What can Merrin contribute?", "Merrin has conversations about accurate records, helping without taking over and her own hobbies. Her personal project repairs the chapel register and teaches Gentle preservation. Her chapel improvement adds 1 vitality to each phase of rest at home when food is sufficient, up to the normal maximum of 6. It does not heal someone who is working or away. She also has a comic-play quest, friendships, romance, signature equipment and three trainable field disciplines."], ["Where are Merrin’s other outfits?", "Open her profile, then Appearance & wardrobe. Slot two is the Plum evening dress; slot three is the Plum halter and wrap skirt. The second invitation needs one remembered shared scene. The third needs three distinct scenes, including a new scene after accepting the second invitation. Accept the invitation, then select the outfit while you are both home. Bathing is a separate appearance. The recruit-all cheat includes Merrin but does not skip these invitations."]]},
{"id": "recruitment-reports", "title": "Rescue quests and bandit encounters", "tags": "reports rescue bandit exotic dryad nymph elemental water fire earth air spirit golem", "view": "candidateReview", "sections": [["How do new leads appear?", "After Chapter 4, assign your scholar to collect local reports from Recruitment quests & contacts. One completed phase saves a new identity and quest. New reports are available once per day and the board holds at most three unfinished quests. Reading or reloading a lead does not reroll it."], ["Who can appear?", "Reports normally identify a common ancestry. There is a 1% chance of an exotic ancestry. Golems and spirits never appear as bandits or rescue targets; dryads and nymphs can be rescue targets but never bandits. Elementals have water, fire, earth and air variants, each with matching encounter artwork."], ["How does recruitment work after rescue or capture?", "A rescue requires travelling out, clearing the roadblock and bringing the person home. You can then offer an introduction or wish her well. A bandit lead requires a free Quiet chamber. Reduce the group to half vitality or lower, secure a surrender with Binding thread, and return. Discuss her account, restitution and plans; release remains available. Only a released person who wants to return can accept an introduction."], ["Does an introduction grant household membership?", "No. Discuss expectations, offer a suitable bedroom and Advance for the visit. The visitor’s decision to stay and your household invitation are separate. Neither rescue nor custody creates an obligation to join."], ["Where did Review a new visitor go?", "The normal recruitment board replaces it. Choosing a custom identity and generating its biography are now under Cheats → custom character authoring. Accepting a custom plan marks the campaign as modified. Ordinary scripted reports, named introductions and paid magical arrivals need no model."]]},
{"id": "optional-providers", "title": "Optional APIs and portrait descriptions", "tags": "settings artwork API OpenRouter OpenAI Anthropic Gemini local model appearance styling portrait brief", "view": "settings", "sections": [["What can I configure?", "Text and portrait generation have separate settings. Choose the request format, complete endpoint URL, model and authentication. Supported text formats are OpenAI-compatible chat, Anthropic Messages and Gemini generateContent. Image formats cover OpenAI-compatible base64 images, OpenRouter chat images and Gemini images. Other proprietary formats need a compatible gateway."], ["Can I use a local model?", "Yes, with a compatible local server and its full endpoint path. Select No authentication if the server does not require a key. Local URLs are resolved on the machine running the game server. Saving settings does not send a generation request."], ["What happens to stored API keys?", "Keys stay on the game server and are omitted from public settings and save exports. Changing the endpoint or request format clears the old key unless you supply a new one. Text and image settings remain separate."], ["What is Portrait description?", "This optional field records visible details such as hair, clothing and accessories for future artwork prompts and relevant dialogue. Saving the text does not change a portrait or call an image API. Import or explicitly generate and review artwork separately."]]},
 {id:'ancestry-bonuses',title:'Ancestry bonuses',tags:'ancestry trait bonus kitsune human djinn attributes checks',view:'bestiary',sections:[
 ['What does ancestry change?','Each ancestry has one always-active trait: +1 to capability checks using a particular attribute. Profiles and Creatures and Peoples show the exact trait. Check calculations list it separately. For example, Koharu’s Kitsune trait adds +1 to Dexterity checks; Zahra’s Djinn trait adds +1 to Resolve checks.'],
 ['Does it change training or relationships?','No. Base attributes, skill ranks, advancement costs, preparation slots and relationship gains stay separate. The bonus can help a capability check meet a threshold, including builder expertise or a casting check. It does not grant an additional action, a spell or consent. Optional earned ancestry perks are separate training.']]},
 {id:'scripted-solo',title:'Playing without an AI gamemaster',tags:'offline scripted model provider summoning recruitment character creation journal stories coop',view:'candidateReview',sections:[
 ['Do I need a model or API account?','No. Chapters, expeditions, castle discoveries, invitations, named companion conversations and game outcomes use the built-in rules and stories. Co-op with Eris and Selene remains unavailable.'],
 ['How do I create another companion?','Open People and arrivals → Recruitment quests & contacts. After Chapter 4, collecting local reports takes one assigned phase and creates a saved rescue or bandit lead. Complete that quest before offering an introduction. For magical arrivals, prepare a saved ancestry invitation and finish its paid summoning working. Golems require construction and awakening. Named companions have their own discoveries; Koharu is already a local neighbour. Custom character authoring is a Cheat, not a normal recruitment route.'],
 ['Does approval recruit her?','No. Discuss her intentions, accommodation and visit, offer a suitable available bedroom, then Advance for arrival. A visitor decides separately whether she wants to stay. Membership requires both her agreement and the household’s invitation. Visit-only preferences remain valid.'],
 ['What happens after arrival?','Built-in procedural companions have conversations about their craft, values and interests, with several player responses and saved transcripts. Find them in her Talk tab or her arrival conversation. Prepare personal stories from the Personal stories page; projects use their displayed costs and work phases. Portraits can be imported separately.'],
 ['How is the journal written?','The event log records resolved outcomes. Prepare phase account copies those exact outcomes into a reviewable journal entry without a provider call. Rechecking a request does not create another entry. Optional model-written prose remains an extra editor, never a requirement or authority over game rules.']]},
 {id:'bedroom-occupancy',title:'Bedrooms, quarters & map residents',tags:'housing quarters bedroom residents map occupancy room assignment',view:'housing',sections:[
 ['Where does someone live?','Her profile lists the assigned bedroom, its quarters, bed capacity and anyone sharing it. The map lists assigned residents on each bedroom and on its parent quarters. These assignments remain visible when a resident is working elsewhere or travelling. Here now is a separate list of current room occupants.'],
 ['How do I move someone?','Open Bedrooms and beds, restore a suitable room and change her bedroom assignment. Privacy preferences, capacity and named arrival reservations are checked before the move. Her profile and map update from the same assignment record.'],
 ['How many specialized chambers are there?','One Ember chamber and one Quiet chamber, each for one person. They provide specialized care and add no residential beds. Ordinary underground bedrooms are separate rooms.']]},
 {"id": "foundation-ritual", "title": "Foundation chamber investigation & ritual", "tags": "foundation ritual blessing relationship bonding castle mystery chapter five private evening nine phases twenty percent", "view": "foundationChamber", "sections": [["When can I find the chamber?", "After Chapter 5, open Foundation ritual chamber from Magic or Castle rooms & household. Trace the service line and read its maintenance ledger. The map shows ??? until the ledger identifies the room. Restore it, then complete the isolation and household circuit tests."], ["What does the ritual do?", "An optional intimacy ritual takes one shared phase and fades to black. It increases positive trust, affection, respect and resident bonding gains by 20% throughout the household for the following nine phases (three days), including travellers. For example, a gain of 1 becomes 1.2. It does not grant points on its own or choose anyone’s relationships."], ["Who can take part?", "Your scholar and an adult resident partner must already have shared the Private evening romance milestone, with romantic invitations enabled. Both must be at home and assigned to Rest. Invite the partner, read their response and choose whether to begin. You can decline or cancel an unfinished ritual."], ["What does it cost?", "Restoring the chamber costs 24 crowns, two binding thread, two porous clay and one fireglass. Each ritual costs no additional supplies or crowns. It uses one phase for both participants, so their ordinary work waits."], ["Can I renew the blessing?", "Yes. Completing another ritual refreshes its duration; the percentage never stacks. The chamber and Home show whether it is active and how many phases remain. Score ceilings still apply; bonus bonding does not consume the ordinary four-point daily allowance."], ["Is the ritual required for the story?", "No. You can complete the investigation without romance or a ritual. The castle’s essential wards have a separate supply. Chapter 9 later requires the completed foundation findings and the founding record from Castle history, then investigates the old survey rooms."]]},
 {id:'continuing-conversations',title:'Conversations, preferences & shared traditions',tags:'companion dialogue choices threads memory preference privacy disagreement tradition resident friendship',view:'peopleHub',sections:[
 ['Where do I find the new conversations?','Open a companion’s Talk tab, then Conversations to return to. Her first personal disclosure in About opens a three-exchange conversation. Pairs open after both residents have shared that first disclosure. Follow-ups open one day phase after the preceding conversation finishes. Home invitations and room links lead to the same saved exchange.'],
 ['Can I stop in the middle?','Yes. Every selected response is saved immediately. Leave the page, set the conversation aside, or reload and return to the same exchange. Invitations never expire. Everyone in the conversation must be home to continue; work assignments stay unchanged.'],
 ['What does she remember about me?','Only the answer you explicitly share with her. Each companion asks a different question. You can choose a preference, say you are unsure, or keep it private. Other residents do not automatically learn the answer. Her About and Talk tabs show your latest answer and let you change it when you are both home. Earlier conversations keep their original wording.'],
 ['Must I agree to progress?','No. Respectful disagreement earns the same Trust as agreement. It can remain unresolved in a later conversation. Completing a conversation gives Trust +1 per present pair once, up to the existing maximum of 12. Resident pairs also earn their normal scene bonding, subject to the existing daily limit. An active foundation blessing increases eligible gains by 20%. Reading, correcting preferences and rereading history give no extra reward.'],
 ['What do shared traditions do?','A follow-up offers a specific activity to return to together. Accepting records that shared intention in her profile. Choosing only this visit is equally valid. These agreements do not automatically schedule visits, assign work, spend supplies or advance romance.'],
 ['Where are the full conversations?','Expand Read all saved exchanges within the conversation. Finished conversations also appear in Journal → Memories, with your exact selected responses. Unfinished conversations appear under shared stories and can be resumed from their record.'] ]},
 {id:'bestiary',title:'Creatures, peoples & bounties',tags:'bestiary ancestry creatures people bounties rare components materials library study',view:'bestiary',sections:[
 ['Where is the field guide?','Open Adventures → Creatures and Peoples. Switch between creatures and ancestry references. Search by name, habitat or physical traits, and filter creatures by knowledge or challenge rank. All 30 creatures are sorted as Standard (11), Intermediate (14) or Difficult (5). The rank is visible before discovery; detailed counters and combat knowledge still need to be learned. Ancestry entries describe shared traits, not a person’s personality or allegiance.'],
 ['How do I complete a creature entry?','A patrol or bounty records a sighting. Resolve its encounter, complete its bounty, or assign one scholar phase to study an observed creature in the library. Names, illustrations and habitats are available before discovery; field knowledge is earned during play.'],
 ['How are bounties different from hunting?','After Chapter 7, Creature bounties offers client requests with exact crown and material rewards. Review the party and requirements before departure. Advance resolves travel and encounters. Household Hunting remains the separate repeatable food task.'],
 ['Where do rare materials go?','Creature entries list their rare component, ordinary material rewards and advanced uses. Follow Review work to equipment refinements, enchanting or room improvements. Regular suppliers do not sell rare components. A sample client keeps one of the two recovered components; a clearance client leaves both.'],
 ['What do the five difficult drops make?','Two Basilisk scales make the Basilisk mirror brooch; two Manticore spines make the Manticore barb ring; two Wyvern venom crystals make the Wyvern antivenom locket; two Hydra resins make the Hydra heart charm; two Colossus ward keys make the Colossus ward talisman. Each also needs Silver ivy, Binding thread, crowns, learned principles and six equipment-work phases in the Enchanting room. All occupy the accessory slot and use no inscription channel. Exact benefits and costs are in Equipment → Make equipment.'],
 ['How do special creature conditions work?','The encounter shows preparation, current conditions and creature counters. Physical counters work without learned spells. First aid in difficult encounters uses one unreserved Silver ivy to restore 2 vitality and clear venom and stone stiffness; the Field remedy cabinet raises this to 3. Conditions change only on committed exchanges and end with the encounter. Every action preview includes secondary attacks, poison and regeneration.'],
 ['What does the bestiary cheat reveal?','Fill out the bestiary completes knowledge entries. It does not grant materials, victories, recruits or chapter progress. Cheats change the selected save immediately and record that it was modified.'] ]},
 {id:'patrolling',title:'Field patrols & Chapter 8',tags:'patrol solo party combat mythical rewards watchtower eight',view:'fieldPatrols',sections:[
 ['When can I patrol?','After Chapter 4, open Adventures → Field patrols for a short Supply road patrol. Chapter 7 unlocks intermediate routes, bounties and operations. Chapter 8 opens the three difficult expedition routes and five difficult-creature bounties. Choose one to four household members. Companions need their existing fieldwork agreement; everyone needs at least 3 vitality. Your scholar can stay home on repeatable patrols. Only one field patrol can run at a time.'],
 ['How does it work?','Departure activates each selected expedition equipment set and pauses their household work. Advance once to arrive. Select an actor and method, then Advance to resolve one exchange. A waiting decision causes no automatic battle or injury. Advance once after the last encounter to return. Short road patrols and difficult expeditions have one encounter; intermediate circuits have two. Difficult expeditions and their bounties unlock after Chapter 8.'],
 ['What affects combat?','Weapons add 1 damage, a qualified Might/Athletics score adds 1, and active Measured force adds its rank (up to 2). Guarded strike trades 1 damage for 1 cover for its actor. The visible enemy intent names its target; another actor’s guard does not protect that target. Protection or a shield adds 1 cover, Warded cover adds 1, and a second standing party member adds 1. Prepared personal techniques and supported prepared combat/healing spells keep their costs. Ice prevents retaliation; healing restores up to 3 vitality to the most injured party member. Protective techniques and Cover actions intercept for the threatened companion. Control techniques reduce incoming force by 2 and open the next damaging action for +1 damage. Healing resolves before the enemy attack. The preview and resolution use the same calculation; expand it for every resulting vitality value.'],
 ['What do the new combat spells do?','Stoneguard protects a selected member with +3 cover for this and two further exchanges. Gust strike deals 2 damage, disrupts retaliation and creates an opening. Binding snare reduces a solid living foe’s force by 2 for this and two further exchanges. Purifying light restores 1 vitality and clears venom, stone stiffness, corrosion and imbalance from a selected member. Dispel ward removes up to two colossus plates and suppresses applicable armor or concealment. Chain lightning deals 5 damage (7 to constructs), with 2 extra damage against raider groups or a hydra and up to two ward plates disconnected. Costs, targets and resulting vitality appear before commitment.'],
 ['Can I prepare protection before leaving?','Expedition warding and Antivenom preparation are repeatable two-person rituals at home. Warding gives the next field party +1 cover for its first three exchanges; antivenom supplies two shared doses that each prevent one venom application. Preparation takes two shared phases, or one for a qualified pair. Costs respect protected reserves. Each prepared batch waits for the next patrol departure, and remaining charges end on return or retreat. These preparations are separate from permanent household circles.'],
 ['How does signature gear grow?','Complete its signature request and equip the piece for work or patrols. Two different accomplishments unlock rank one; four unlock rank two. Enemy types, commission types, practical work, protection, healing and completed objective tasks can count. Choose Precision, Shelter, Care or the owner’s personal refinement on the same item. Refinement takes paid equipment work, respects reserves and stows the item; equip it again afterward. Only one refinement is active, and it uses no inscription channel. You can change it at home for 4 crowns and one work phase.'],
 ['What do I earn?','Resolved encounters pay crowns, provisions and materials on return, including peaceful resolutions. Rare creatures yield two enchanting components. First resolution of each enemy type awards each returning participant 1 advancement point, at most six points per character from enemy types. Repeats still pay resources. A detour bypass gives no encounter reward.'],
 ['Can I retreat?','Yes, before a returning phase. Retreat takes one Advance, keeps earned encounter loot, refunds an unresolved spell’s components and grants nothing for unfinished encounters. If everyone is incapacitated, the party automatically falls back. There is no permanent injury or equipment loss. Returned characters are assigned Rest and need later phases to heal; arrival does not count as overnight sleep.'],
 ['Does patrolling consume extra food?','No. Travellers eat through the existing household provisions system. There is no separate ration charge. Road watch remains a different, passive household task.'],
 ['How does Chapter 8 differ?','Three authored outings require your scholar: trace the missing delivery, reopen the supply route, and hold the castle approach. Rest the returning story party overnight between outings and before the closing supper. Choose a detour, settlement offer or interception plan. No attack begins until you dispatch the story party. Complete the chapter to choose one permanent patrol improvement.'] ]},
 {id:'getting-started',title:'Getting started',tags:'beginner first chapter goal objective',view:'castle',sections:[
 ['What should I do first?','Follow the current chapter on Castle. Its next-step card names the action, its requirements and where to do it. You can stop to talk, decorate or explore other available systems at any time.'],
 ['What saves my progress?','Successful actions save automatically to this server. Opening screens and reading Help do not advance time. Use New game & saves to switch campaigns or download a backup.'],
 ['Why is a button unavailable?','Select or hover over an unavailable action to read its requirements. Common causes are a missing room, insufficient unreserved supplies, a character being away, or unfinished work.'] ]},
 {id:'time',title:'Time, assignments and sleep',tags:'advance phase morning afternoon evening rest night pause work',view:'phaseTasks',sections:[
 ['How does time pass?','Only Advance moves time: morning → afternoon → evening → the next morning. The evening Advance includes the night. There is no separate sleep phase and no real-time countdown.'],
 ['What happens when I press Advance?','Each character performs their assigned task if its conditions are met. Travel and deliveries also progress. Preview Advance lists the expected changes before you commit. A newly finished job does not automatically give its worker a second action.'],
 ['What do project progress numbers mean?','The first number is completed work; the second is the total needed. Crafting and construction use work points: more workers or bonuses can add several points in one phase. Training and travel keep their listed phase durations. The Advance preview shows what will progress next.'],
 ['Can I pause a project?','Yes. Assigning different work usually pauses a paid project and keeps its progress. Resume it from Projects or its own screen. Cancelling is different: check the displayed refund before choosing it.'],
 ['What is field health?','Field health is the current vitality used in patrols and expeditions, from 0 to 6. It is separate from the Vitality attribute on a character’s sheet. Rest at home or use healing to recover; patrols require at least 3.'],
 ['How do I rest?','Choose Rest for a character. At home, rest restores health. An evening rest records that the character slept before the next morning; some later chapter scenes require this. Home shows evening wind-down choices. They assign your character to Rest without advancing time. For a returning party or Rhess’s patrol, a separate button names exactly who will rest. The next morning offers links to resume paused work.'] ]},
 {id:'chapters',title:'Chapters and quests',tags:'story goals progress journal milestones',view:'goals',sections:[
 ['What do chapters cover?','Chapter 1 introduces a home, ordinary equipment and a practical spell. In Chapter 2, finish one chosen undertaking; the others stay optional. Chapter 3 opens a usable lower wing with a practical facility; extra leisure rooms are optional. Chapter 4 secures the entrance and teaches defense; containment is only needed if you choose it. Chapter 5 teaches enchanting and opens the foundation-chamber investigation. Chapters 6–8 develop supplies, a shared watch and coordinated defense. Rhess may help Chapter 7 as a guest ally. Chapter 9 follows the old survey connections and answers why the castle was a stable reference point.'],
 ['Why is the next scene locked?','Chapter requirements can include completed construction, an expedition, a conversation, a later day or overnight rest. Completing a task early may meet a requirement, but does not skip the chapter conversation. Read the specific reason beside the locked step.'],
 ['Do invitations expire?','Personal invitations can wait. Setting one aside hides it from the active invitation list; it does not delete the story. Journal gathers active quests and completed memories.'] ]},
 {id:'rooms',title:'Rooms, bedrooms and construction',tags:'castle building restore bed accommodation capacity annex',view:'headquarters',sections:[
 ['What does restoring a room do?','It makes that room available and unlocks the activities listed on its construction card. Some improvements must be built separately after the room is ready. Funding construction pays its listed cost; assigned work then completes it over the listed phases.'],
 ['How do I use the full castle map?','Open Castle rooms & household → Castle map, or expand the map on Home. Stair buttons connect the ground, upper and lower levels; passages open the grounds and annex. A furnished room is ready. Rubble means repairs are needed. A progress bar shows work underway or paused. Choose a room to open its real construction or activity controls. The map refreshes from your save after work completes.'],
 ['What do the question marks mean?','??? marks an undiscovered special room. Its name and illustration stay hidden until the relevant investigation identifies it. Ordinary unrepaired rooms keep their names. Finishing construction does not automatically finish the room’s story, circuit tests or personal improvements.'],
 ['Why is a portrait beside the room illustration?','Some character portraits include their own scenery. They are displayed beside the room so their background does not cover it. Opening a room does not move a resident there; presence follows their actual activity.'],
 ['What counts as a bedroom?','A bedroom has a fixed number of beds. Residents, expected arrivals and beds you have reserved all use that capacity. A character who requests a private room needs a one-bed room. A dungeon chamber is not a bedroom.'],
 ['Can several people build at once?','Each agreed builder can run their own eligible headquarters project. A worker still has only one current assignment. Check each project’s worker and progress; assigning more people elsewhere does not automatically accelerate it.'] ]},
 {id:'companions',title:'Meeting and recruiting companions',tags:'unique resident recruit contact visit stay summoning arrival',view:'contacts',sections:[
 ['How do companions join?','Meet them through their introduction, expedition, correspondence or summoning route. Discuss the available topics, offer suitable accommodation, and advance time for an agreed visit. For visiting candidates, ask whether they want to stay and choose to invite them into the household.'],
 ['Does summoning recruit someone?','No. It opens contact. Visiting and joining are later decisions. Construction creates a golem’s body before awakening; it does not summon an existing person. The requirements on each candidate’s card tell you which route applies.'],
 ['Who is the Djinn smith?','Zahra is the Djinn companion associated with the smithy. Restore the conservatory to discover her letter, then use her exotic-contact route. Making contact, agreeing a visit and joining the household remain separate steps.'],
 ['Where is a companion’s room bonus?','Open Companions, choose the character, and read Room specialty on Overview. It names the room, exact benefit, installation status and requirements. Most bonuses require building the improvement first. Mira uses her Library archive project.'],
 ['Where are a resident’s systems?','Open their character sheet. Overview shows their current situation. Conversation holds dialogue and activities; Quests & stories holds personal work; Build holds equipment and training; Relationships holds friendship and romance.'],
 ['Can I recruit someone immediately?','Cheats offers individual unique companions or all remaining unique companions. This bypasses their recruitment requirements, adds suitable beds when needed and marks the save as modified. It does not complete their personal quests or raise romance.'] ]},
 {id:'work',title:'Resident work and projects',tags:'tasks copying crowns commissions procurement training work agreements',view:'householdWork',sections:[
 ['How do I assign work?','Choose a resident and an available task. Some work requires an agreement, a room or an active project first. The task explains its output. Results arrive when you press Advance.'],
 ['Why can’t I assign Research?','Research work needs an active study. Open Magic → Research and begin an unfinished study first. Then household members can help it. The unavailable-task explanation links directly to Research. Learning, crafting, spell work and other project tasks similarly link to their own setup screen and name the missing work. A character who is away must return before you assign castle work.'],
 ['Why did progress stop?','The worker may be away, assigned elsewhere, or waiting for a requirement. Review the project’s displayed reason, then use Resume. Materials already paid into a paused project are not paid again.'],
 ['How do I earn crowns?','Assign your character to copying commissions. Its current income per phase is shown beside the action. Chapter funding guidance offers Earn for this project: it sets a treasury target and stops copying after a phase reaches it. Food purchases and other spending can extend the estimate. Pause or resume the plan on Home; nothing is purchased automatically. Expeditions and other unlocked jobs offer additional income. Crowns in the shared treasury pay household costs; personal funds belong to individual residents.'] ]},
 {id:'food',title:'Food and the pantry',tags:'hunger provisions starving hunt forage kitchen automatic purchase',view:'stores',sections:[
 ['When is food used?','The household eats once per day when evening advances to morning. Each household member, including travellers, uses one provision. A restored kitchen lowers total daily use to 80%, rounded up. The pantry displays the current daily requirement.'],
 ['How do I obtain food?','Buy six provisions for one crown, assign hunting or foraging, or bring supplies home from expeditions. Gathering yields at least six per assigned phase; skill and a preferred task can increase it. Food does not expire.'],
 ['Can food be supplied automatically?','Enable automatic purchases and set a target stock, daily budget and minimum treasury balance. Purchases happen before the daily meal and respect those limits. Velis’s completed room specialty can provide up to four provisions daily without spending crowns, limited by your pantry target.'],
 ['How does the food ritual work?','After your character learns Steady hearth wards, Conjure Sustenance uses one silver ivy and one binding thread. Two assigned ritual phases produce 18 provisions.'],
 ['What happens if food runs out?','Three consecutive days without a full household meal reduce rest healing to at most one health per phase. A full meal clears the shortage. Nobody dies or loses relationship progress from hunger.'] ]},
 {id:'supplies',title:'Materials, reserves and supply orders',tags:'store buy silver ivy binding thread crowns reserve target velis warehouse',view:'stores',sections:[
 ['What does unreserved mean?','Unreserved stock is your inventory minus the amount you have chosen to protect. Many projects can spend only that remaining stock. Lower a reserve target or obtain more material if a project says you do not have enough unreserved supplies.'],
 ['How do I buy supplies?','Stores sells core materials for crowns. The Supply Office also offers bulk orders: review the price and confirm it, then allow two phases for delivery. Up to four orders can be outstanding.'],
 ['What does Velis change?','While Velis is home and assigned to procurement, Supply Office material orders receive a larger discount. Her food specialty is a separate improvement. The order preview shows the actual price before you pay.'] ]},
 {id:'expeditions',title:'Expeditions and returning home',tags:'adventure travel party routes encounters retreat survey',view:'expeditions',sections:[
 ['How do I prepare?','Choose an available site, read its travel plan, and select willing companions. Check their expedition equipment, prepared spells and health. A person who is away cannot perform castle work at the same time.'],
 ['How do obstacles work?','At the site, choose one of the displayed methods. Each method lists who acts, its requirements, supplies and duration. Specialist methods may be faster; an ordinary method remains available where the site offers one.'],
 ['Can I leave early?','Use Return or Retreat. Travel home still takes its listed time. Completed discoveries and saved encounter progress remain where the site supports them; returned supply costs are shown in the result.'],
 ['Where are my rewards?','Review the return report. Many discoveries pay once, so revisiting a completed route does not repeat its first-completion reward.'] ]},
 {id:'combat',title:'Combat and health',tags:'damage enemy attack defense armour healing injury retaliation',view:'expeditions',sections:[
 ['When does an enemy attack?','Combat is resolved through encounter actions, not a real-time battle. Read the method’s damage and retaliation information before choosing it. Enemy health and your party’s health are displayed in the encounter.'],
 ['What helps in combat?','Weapons, active enchantments, prepared techniques and spells can improve suitable actions. Their benefits depend on the method and the acting character. A room or an item in storage does not automatically give everyone its combat effect.'],
 ['How do I recover?','Rest at home or use an available healing action. Health is capped at six. A character at zero health needs recovery before taking field actions; read the action’s health requirement.'] ]},
 {id:'equipment',title:'Equipment and equipment sets',tags:'build head shirt pants hands boots ring necklace accessory dress two handed signature weapon',view:'armoury',sections:[
 ['Which slots are available?','Head, shirt, pants, hand 1, hand 2, boots, ring, necklace and accessory. A dress can occupy shirt and pants; a two-handed weapon can occupy both hands. Equipping one replaces any item using those slots.'],
 ['What is an equipment set?','A saved set of equipped items and active enchantments. Household and expedition equipment sets are separate. An item must be equipped in the relevant equipment set for its effects to apply.'],
 ['How does equipment improve?','The game does not use a ladder of increasingly rare metals. Ordinary weapons and armour become more useful through customization, signature development and enchantments. Each item’s panel shows its available upgrades.'],
 ['What is a signature item?','A character’s personal weapon or tool that develops through their own request and customization choices. Some advanced talents require the finished signature item to be equipped.'] ]},
 {id:'enchanting',title:'Enchanting equipment',tags:'inscription capacity channel resonance smithy workshop gear',view:'armoury',sections:[
 ['How do I enchant an item?','Open Equipment, select the item and choose an available enchantment job. The preview lists the worker, required rooms and knowledge, cost and work phases. The equipment is unavailable while committed to that job.'],
 ['Why is an enchantment not working?','Learning or inscribing an enchantment is different from activating it. Equip the item and enable the enchantment in the equipment set you use. Item capacity and active-channel limits can prevent activating everything at once.'],
 ['Can I enchant clothing and accessories?','Yes. Enchanting is part of the unified equipment system, including clothing, armour, weapons, tools and accessories. The item’s current options show which effects can be applied.'] ]},
 {id:'builds',title:'Attributes, skills and personal paths',tags:'character build training talent technique passive advancement affinity practice',view:'development',sections:[
 ['Where do I customize a build?','Open a character’s Build tab. Equipment & abilities gathers their equipment and preparations. Personal paths lets you choose their individual talents. Training holds attributes, skills and other learning.'],
 ['What are advancement points?','Points earned from qualifying discoveries and achievements. They pay for training that lists an advancement cost. They are separate from crowns and resonance. Available points exclude those already spent or committed.'],
 ['What are personal paths?','Each named character has three paths with distinct talents. Learn a talent through its assigned training, then prepare it if required. Preparing a different technique may require replacing one already prepared. Passive talents apply under their listed conditions.'],
 ['What does a saved build contain?','Complete build presets save supported preparations together, including physical equipment and personal-path choices. Loading a preset still checks whether its pieces and prerequisites are currently available.'] ]},
 {id:'magic',title:'Research, principles and spells',tags:'spellbook archive learn prepare cast focus ritual knowledge',view:'spells',sections:[
 ['What is a principle?','A piece of magical knowledge used to qualify for research, crafting or spells. Discovering it for the archive does not teach it to every resident. The chosen worker or caster must personally learn required principles.'],
 ['What is the difference between learning and preparing?','Learning makes a spell or practice known to a character. Preparing selects it for use within that character’s available slots. Known but unprepared options do not provide their prepared effects.'],
 ['How do I cast?','Select a known spell, review its target and material cost, and assign the casting work. Advance completes its listed work phases. Field spells use the expedition controls and their displayed requirements.'],
 ['Do I need an external AI service?','No. The scripted game, authored spells and included stories work without one. Optional text drafts require separate settings and review; a draft cannot grant items or change game rules.'] ]},
 {id:'relationships',title:'Friendship, romance and time together',tags:'affection trust relationship milestone intimate scenes repeat invitation',view:'peopleHub',sections:[
 ['How do bonds between residents become useful?','Open Companions → Resident friendships. At 10 bonding a pair can share an idea; at 25 they can make a keepsake for 4 crowns and one shared phase. Completing it unlocks +1 research work or garden/gathering output when both do the same supported task. At 45 they can share a follow-up activity; at 60 they can establish their shared tradition; at 70 cooperation becomes +2. Invitations have no deadline.'],
 ['Where do resident bonding levels come from?','Each pair of residents shares one bonding score from 0 to 100, shown on both profiles. Working on supported tasks together, shared leisure in a usable room, lessons, rituals, outings, conversations and household meals can increase it. Each pair normally earns up to four points per day; repeating the same recorded source does not pay twice. The foundation blessing adds its 20% bonus separately. This is distinct from your scholar’s trust, affection and respect.'],
 ['Does friendship require romance?','No. Conversations, personal projects and shared activities develop the relationship without requiring flirting. Choose friendly responses when that suits the relationship you want.'],
 ['How does romance progress?','Use the companion’s Relationships tab. Each milestone lists its requirements and offers a clear response. Relationship progress does not replace the separate requirements for quests, outfits or work.'],
 ['What is Time together?','Each unique companion has four repeatable affectionate scenes and four one-time milestone scenes. Later stages require the corresponding romance progress and earlier scenes. Some require a later phase, a later day, or a private evening.'],
 ['Can I pause or replay a scene?','You can accept closeness, choose quiet company or leave. Pausing romance does not erase past memories. Replay available scenes from Time together; repeats do not farm resources or relationship rewards.'] ]},
 {id:'personal-corner',title:'Wardrobe and personal corners',tags:'personal space decoration keepsake memento outfit appearance room',view:'peopleHub',sections:[
 ['What is a personal corner?','A small furnished area belonging to one character: a reading nook, making shelf, indoor garden or another listed design. Put it in its matching restored communal room or the character’s assigned bedroom.'],
 ['What does it cost and do?','Each design costs four crowns and one listed material the first time you fit it. Moving or refitting an owned design is free. Give it a name, display an earned keepsake and share its personal scene. The corner itself gives no combat or production bonus.'],
 ['When do companions wear bathing outfits?','During personal time in a restored pool, sauna or hot springs, companions automatically use their bathing outfit. It follows their actual room, not the page you open. Leaving, returning to work or going on an expedition restores their normal appearance without changing their saved wardrobe. Choose an afternoon leisure room under Conversation → Tastes & personal invitations, or let their daily routine choose.'],
 ['How does wardrobe customization work?','Choose an unlocked illustrated outfit or create a named ensemble from garment options. Written ensemble changes describe that style; they do not automatically generate a new portrait. Equipment slots and cosmetic outfit choices have separate controls.'] ]},
 {id:'dungeon',title:'The dungeon and recruitment',tags:'containment capture sabine chamber care release',view:'containment',sections:[
 ['What is the dungeon for?','Its fitted chambers hold the specific encounters they are compatible with. Restore the dungeon, then fit a suitable chamber. Each case explains the problem and the required care. A chamber supplies containment capacity, not a household bed.'],
 ['How does a case end?','Discuss the case and complete its agreed resolution before ordinary release. You can also arrange transfer to specialists. Arrival and departure happen on Advance; a chamber remains occupied or reserved until then.'],
 ['How do common bandit recruits work?','After Chapter 4, ask for bandit reports in Recruitment quests & contacts, then prepare a patrol for the saved lead and reserve a free Quiet chamber. Common ancestries are usual; exotic bandits have a 1% chance. Spirits, golems, dryads and nymphs never appear as bandits. Reduce the bandits to half vitality, then choose Secure a surrender with one unreserved Binding thread. Return home, hear three dungeon topics across separate day phases, and release her. Agreement on at least two topics makes a trial invitation available. You may release her without an agreement at any time. Housing and membership keep their ordinary requirements.'],
 ['How do rescue recruits work?','Follow a rescue lead from People and arrivals or a named neighbour’s route notes. Clear one raider roadblock and return home. You may then offer an introduction or wish the traveller well. The quest does not automatically add a resident or reserve a bedroom. Unfinished outings leave the lead available.'],
 ['Does resolving a case recruit the character?','No. After release, correspondence and a normal visit can lead to membership. The character needs suitable residential accommodation and must agree to stay. Recruitment and romance are separate from resolving the case.'] ]},
 {id:'cheats',title:'Cheats and backups',tags:'instant recruit spawn food equipment advancement heal modified save',view:'cheats',sections:[
 ['How do I enable cheats?','Open Cheats and enable them for the current save. Your character must be home to apply a cheat. Each change saves immediately and is recorded in cheat history.'],
 ['What can I change?','Add crowns, resonance, food or materials; finish rooms or containment chambers; create equipment or crafted objects; grant knowledge or advancement; restore health; fill out the bestiary; generate an ordinary resident; or recruit unique companions immediately. Each control explains what still requires ordinary play.'],
 ['What does completing a room skip?','It finishes the selected room or chamber immediately, keeping any construction payments already spent. An annex bedroom also completes its supporting annex. It does not complete care cases, personal improvements or chapter conversations. The Foundation chamber appears only after you read its ledger; its shortcut completes physical restoration while leaving both circuit tests and all ritual eligibility requirements in place.'],
 ['Do cheats grant relationships or a ritual blessing?','The current tools do not grant trust, affection, respect, resident bonding, romance milestones or the foundation blessing. Recruitment keeps existing relationship progress. Complete the ordinary conversations, activities and mutual ritual invitation to develop those systems.'],
 ['Can I undo a cheat?','Disabling cheats does not undo changes or remove the modified-save label. Download a backup before using them if you want to keep an unchanged copy.'],
 ['What does instant recruitment skip?','It bypasses the selected unique companion’s introduction, recruitment quest and arrival requirements, resolves conflicting pending arrivals, and provides a suitable bed when one can be restored. It keeps their identity and existing progress. It grants neither romance, personal-goal completion nor chapter completion.'] ]},
 {id:'resonance',title:'Resonance and decoration',tags:'atmosphere furnishings velvet settee violet glow points',view:'resonance',sections:[
 ['What is resonance?','A castle atmosphere score. It is separate from money, advancement and relationship progress. Welcomed flirtation and established romantic relationships can contribute while the plum settee is placed in the common room. The Resonance screen lists the current contributors and gain.'],
 ['What does it change?','At six resonance, a violet hearthlight appears in the common room. The Resonance screen shows your current score and expected gain per Advance. The light is cosmetic. At 12 points, the repaired library lamp also supports the optional Resonance lens study; the study does not spend those points.'],
 ['Does decoration advance time?','Choosing furnishings and displaying owned keepsakes does not advance time. Some furniture has a listed gameplay effect; other decorations are cosmetic. Read the item’s effect before buying or placing it.'] ]},
 {id:'glossary',title:'Common terms',tags:'glossary definitions terminology work phase preparation own contribution resonance',view:'castle',sections:[
 ['Phase and work','A phase is one morning, afternoon or evening. A work point measures progress made during an assigned phase; bonuses can sometimes increase that progress. Training and travel use their own listed durations.'],
 ['Crowns, provisions and resonance','Crowns are money. Provisions are stored food. Resonance is an atmosphere score from specific shared flirtations and furnishings. Its current recurring gain is shown on the Resonance screen; it is not a general building or experience score. These are separate resources.'],
 ['Requirement, prerequisite and blocker','All mean something you must satisfy before an action is available. The displayed reason should name the missing condition.'],
 ['Prepared, equipped and installed','Prepared means selected for use by a character. Equipped means occupying the appropriate equipment slots. Installed means placed in a room or activated as a household improvement. Owning something alone may not activate its effect.'] ]}
];
const HELP_ROUTES={candidateReview:'recruitment-reports',personalStories:'scripted-solo',castleMap:'rooms',surveyRooms:'chapters',magicReference:'magic',residentFriendships:'relationships',foundationChamber:'foundation-ritual',bestiary:'bestiary',bounties:'bestiary',hqRoom:'rooms',commissions:'refinements',practicalProjects:'refinements',sharedHistory:'refinements',workArrangements:'refinements',fieldPatrols:'patrolling',firstRealTest:'patrolling',phaseTasks:'time',castle:'getting-started',goals:'chapters',firstHearth:'chapters',houseShape:'chapters',roomToGrow:'chapters',keepingHearth:'dungeon',armsOfOurOwn:'enchanting',roadsWeKeep:'supplies',firstPatrol:'combat',headquarters:'rooms',housing:'rooms',estateHub:'rooms',room:'rooms',contacts:'companions',summoning:'companions',localEncounters:'companions',peopleHub:'companions',householdWork:'work',progression:'work',provisions:'food',resonance:'resonance',stores:'supplies',ledger:'supplies',expeditions:'expeditions',armoury:'equipment',development:'builds',spells:'magic',research:'magic',containment:'dungeon',cheats:'cheats',customization:'personal-corner'};
function helpForScreen(){return currentView==='characterProfile'?({development:'builds',relationships:'relationships',style:'personal-corner',space:'personal-corner',quests:'chapters',talk:'relationships'}[uiCharacterTab]||'companions'):(HELP_ROUTES[currentView]||'getting-started');}
function helpLink(topic=helpForScreen()){return `<button class="text-button help-context-link" data-help-topic="${topic}">Help with this screen</button>`;}
function helpPage(){
 const query=helpQuery.trim().toLowerCase(),found=HELP_TOPICS.filter(t=>(t.title+' '+t.tags+' '+t.sections.flat().join(' ')).toLowerCase().includes(query));
 const selected=found.find(t=>t.id===helpTopic)||found[0];
 return heading('GAME GUIDE','Help','Choose a topic or search for a word. Reading this guide does not advance time.')+`<label for="help-search">Search Help<input id="help-search" type="search" value="${escapeHtml(helpQuery)}" placeholder="Food, sleep, recruiting, enchantments…"></label><p role="status">${found.length} topic${found.length===1?'':'s'} found</p><div class="help-layout"><nav class="help-topics" aria-label="Help topics">${found.map(t=>`<button data-help-topic="${t.id}" aria-current="${t===selected?'page':'false'}">${escapeHtml(t.title)}</button>`).join('')}</nav><article class="panel help-article">${selected?`<h2>${escapeHtml(selected.title)}</h2>${selected.sections.map(([q,a])=>`<section><h3>${escapeHtml(q)}</h3><p>${escapeHtml(a)}</p></section>`).join('')}<button data-view="${selected.view}">Open related screen →</button>`:'<h2>No matching topic</h2><p>Try a shorter search, such as “food” or “sleep”.</p><button data-help-clear="yes">Show all topics</button>'}</article></div>`;
}

