function assignmentLabel(key){
 const labels={'local-reports':'Collect local reports','survey-rooms':'Survey room investigation','resident-friendship':'Shared friendship activity','foundation-work':'Foundation chamber investigation','foundation-ritual':'Private chamber ritual',rest:'Rest',commissions:'Copy records for income','external-commission':'External commission','practical-project':'Companion improvement','castle-lamp':'Library lamp work','local-reports':'Collect local recruitment reports', 'bestiary-study':'Bestiary study',research:'Hearth research',archive:'Shared research',crafting:'Artifact crafting',headquarters:'Room construction or improvement',facilities:'Living-wing restoration',housing:'Bedroom construction',restoration:'Conservatory restoration',garden:'Garden work',training:'Training',teaching:'Teaching a lesson',inscribing:'Equipment inscription',spellwork:'Spell learning or casting','equipment-work':'Equipment work','signature-fitting':'Signature equipment fitting','equipment-review':'Equipment practice','house-shape':'Chapter 2 construction','household-story':'Shared household project','shared-review':'Joint research review','personal-request':'Personal keepsake','public-project':'Expanded catalogue project',mystery:'Castle investigation','personal-project':'Personal project','archive-project':'Archive improvement',containment:'Dungeon care or construction',estate:'Annex construction',ritual:'Group ritual',augmentation:'Personal ritual',expedition:'On expedition','field-patrol':'On field patrol','field-watch':'On field patrol',hunt:'Hunting',forage:'Foraging',procurement:'Buying provisions','road-patrol':'Road watch','food-ritual':'Food-preserving ritual'};
 return labels[key]||String(key||'No assignment').replaceAll('-',' ').replaceAll('_',' ');
}
const escapeHtml = value => String(value).replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const titleCase = value => value.charAt(0).toUpperCase() + value.slice(1);
const assetUrl = id => state.assetOverrides[id] ? campaignUrl(state.assetOverrides[id]) : state.originalAssets[id];
const portraitId = () => state.bathingOutfitView?.mira?.active ? state.bathingOutfitView.mira.portraitId : state.outfitProgressionView?.mira?.portraitId || 'mira';
const actionButton = (action, label, css = '') => action==='advance' ? advanceButton(label,css) : `<button class="${css}" data-action="${action}" ${state&&!state.founderAtCastle&&['conversation','invitation','start-research','start-restoration','celebrate-living-wing','start-archive-project','finish-archive-story','install-index-charm'].includes(action)?'disabled title="Your scholar must be at the castle"':''}>${label}</button>`;
function toast(message) {
  const element = document.querySelector('#toast');
  element.textContent = message; element.classList.add('visible');
  clearTimeout(toastTimer); toastTimer = setTimeout(() => element.classList.remove('visible'), 5000);
}
async function readState() {
  const response = await fetch(campaignUrl('/api/state'), {cache:'no-store'});
  if (!response.ok) throw new Error('Could not read the saved campaign.');
  return response.json();
}
function newRequestId() {
  return Array.from(crypto.getRandomValues(new Uint8Array(16)), byte => byte.toString(16).padStart(2,'0')).join('');
}
async function commit(action, message, followup) {
  if (busy || pendingRequest) return;
  uiPendingForm=uiSubmittedForm;uiSubmittedForm=null;
  pendingRequest = {requestId:newRequestId(), expectedRevision:state.revision, action};
  await sendPending(message, followup);
}
async function sendPending(message = 'Saved.', followup) {
  const savingCraft = pendingRequest?.action?.type === 'start-crafting';
  const submitted=uiPendingForm;
  busy = true; document.body.classList.add('busy');
  try {
    const response = await fetch(campaignUrl('/api/action'), {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pendingRequest)});
    const result = await response.json();
    if (!response.ok) {
      if (result.state) state = result.state;
      pendingRequest = null;uiPendingForm=null;
      throw new Error(result.error || 'The action could not be saved.');
    }
    state = result; pendingRequest = null;uiPendingForm=null;
    if(submitted)clearUiDrafts(submitted);
    if (savingCraft) craftingError = '';
    if (followup) followup();
    render();
    if(['arrival','characterSetup'].includes(currentView))document.querySelector('#main-content')?.focus?.({preventScroll:true});
    if (message) toast(message);
  } catch (error) {
    if (savingCraft) craftingError = error.message;
    render();
    toast(pendingRequest ? 'Connection interrupted. Retry the pending save to safely confirm its result.' : error.message);
  } finally {
    busy = false; document.body.classList.remove('busy');
  }
}
function navButton(id, icon, text) {
  const active = currentView === id || Boolean(SYSTEM_GROUPS[id]?.views.some(v=>v[0]===currentView)) || (id === 'castle' && currentView === 'room') || (id === 'household' && ['conversation','companion'].includes(currentView));
  return `<button class="nav-button ${active?'active':''}" data-view="${id}" ${active?'aria-current="page"':''}>${navigationIcon(id,icon)}${text}</button>`;
}
function render() {
  uiPortraitCache=null;
  if(!state.characterCatalog[selectedCharacterId]) selectedCharacterId='founder';
  if(currentView==='characterSetup'){mountUnifiedUI(presentUI(characterSetupPage()));return;}
  if(currentView==='arrival'){mountUnifiedUI(presentUI(arrivalPage()));return;}
  if(currentView==='start') {mountUnifiedUI(presentUI(startScreen()));return;}
  const group=Object.entries(SYSTEM_GROUPS).find(([key,g])=>g.views.some(v=>v[0]===currentView));
  const html=`<a class="skip-link" href="#main-content">Skip to content</a><div class="app-shell"><aside class="sidebar" data-ui-key="sidebar"><div class="brand"><img class="brand-logo" src="/assets/ui/stonework-and-spellcraft-logo-v074.webp" alt="Stonework and Spellcraft" width="1200" height="800"></div><button class="navigation-toggle" data-navigation-toggle="yes" aria-expanded="${navigationOpen}" aria-controls="main-navigation">${navigationOpen?'Close navigation':'Navigate'} →</button><nav id="main-navigation" class="${navigationOpen?'navigation-open':''}" aria-label="Main navigation">${unifiedNavigation()}</nav><div class="sidebar-bottom"><span class="badge">SOLO · ${state.testing.used?'TESTING MODIFIED':state.startType==='fresh'?'FRESH BEGINNING':'DEMONSTRATION'}</span><div class="save-note">Saved on your server</div></div></aside><div class="workspace"><header class="topbar" data-ui-key="topbar"><div class="campaign-heading"><div class="campaign-title">${escapeHtml(state.campaignName)}</div><small>${state.sharedFunds} crowns · ${Object.keys(state.characterCatalog).length} in the household</small></div><div class="time-control"><button data-view="phaseTasks">This phase · ${state.phaseTasks.count}</button><strong class="header-day">Day ${state.dayNumber}</strong>${dayPhaseIndicator()}<button data-preview-advance="yes">Preview Advance</button>${actionButton('advance',advanceLabel(),'primary')}</div></header>${pendingRequest?`<div class="error-bar">A save needs confirmation. ${actionButton('retry','Retry safely')}</div>`:''}${state.expedition?`<div class="away-banner">${escapeHtml(state.expeditionSite.name)} · Party away<button data-view="expeditions">Continue expedition →</button></div>`:''}<div class="content-grid calm-layout"><main class="main-content" id="main-content" tabindex="-1" data-ui-key="main:${escapeHtml(uiContextKey())}"><div class="page-tools">${unifiedBreadcrumb()}${['castle','peopleHub','characterProfile','development','customization'].includes(currentView)?'':compactHousehold()}${currentView==='help'?'':helpLink()}</div>${preparationReturnLink()}${pageContent()}</main></div></div></div>`;
  mountUnifiedUI(presentUI(html));
  const history=document.querySelector('.dialogue-history');if(history)history.scrollTop=history.scrollHeight;
}
function heading(kicker, title, description, badge = '') {
  return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${description}</p></div>${badge?`<span class="badge">${badge}</span>`:''}</div>`;
}
function rightRail() {
  const recent = state.journal.slice(-3).reverse();
  return `<aside class="right-rail" aria-label="Household overview"><section class="rail-section"><p class="eyebrow">AROUND THE HOUSE</p><div class="resident-row"><img class="portrait-small" src="${assetUrl(portraitId())}" alt="Mira"><div><strong>Mira</strong><small>${state.residentAtCastle?state.rooms[state.residentRoomId].name:'With the expedition'} · ${state.residentAssignment==='personal-request'?'Her personal project':state.residentAssignment==='expedition'?'Fieldwork':state.residentAssignment==='training'?'Learning':state.residentAssignment==='crafting'?'At the workbench':state.residentAssignment==='archive-project'?'Her living index':state.residentAssignment==='garden'?'Tending plants':state.residentAssignment==='archive'?'At the archive':state.currentDayPhase==='morning'?'Reading':state.currentDayPhase==='evening'?'Unwinding':'Taking tea'}</small></div></div>${state.invitationStatus==='available'?`<div class="invitation"><span class="eyebrow">AN OPEN INVITATION</span><br><strong>Tea, with a little mischief</strong><p>“There’s room beside me, you know.”<br>Whenever you feel like it. No expiry.</p>${actionButton('invitation','Join Mira ↗','full')}</div>`:`<p class="bottom-note">A little flirtation has found its way into the household.</p>${actionButton('conversation','Visit Mira →','text-button')}`}</section>${householdInvitationNotice()}<section class="rail-section"><p class="eyebrow">HOUSEHOLD LEDGER</p><div class="resource-row"><span>Shared treasury</span><b>${state.sharedFunds} crowns</b></div><div class="resource-row"><span>Residents</span><b>${Object.keys(state.characterCatalog).length-1}</b></div><div class="resource-row"><span>Day phase</span><b>${titleCase(state.currentDayPhase)}</b></div><div class="resource-row"><span>Castle Resonance</span><b>${state.resonanceStage}</b></div><small>Personal moments and decoration never advance time.</small><div class="forecast-mini"><p class="eyebrow">ON THE NEXT ADVANCE</p>${state.nextPhaseForecast.map(line=>`<p>${escapeHtml(line)}</p>`).join('')}</div></section><section class="rail-section"><p class="eyebrow">RECENT MOMENTS</p><div class="timeline">${recent.map(entry=>`<p><small>DAY ${entry.dayNumber} · ${entry.phase.toUpperCase()}</small>${entry.source==='generated'?'Reviewed account · ':''}${escapeHtml(entry.text)}</p>`).join('')}</div>${actionButton('journal','Open the journal →','text-button')}</section></aside>`;
}
function roomCard(id) {
  const room = state.rooms[id];
  return `<button class="room-card" data-room="${id}"><img class="room-thumbnail" src="${assetUrl(id)}" alt="${room.name} interior" width="800" height="533"><div class="card-copy"><h3>${room.name} ↗</h3><p>${room.purpose}</p>${roomStatusMarkers(id)}</div></button>`;
}
function floorRoom(id, style) {
  return `<button class="plan-room" data-room="${id}" style="${style};--room-art:url('${assetUrl(id)}')"><strong>${state.rooms[id].name}</strong>${roomStatusMarkers(id)}</button>`;
}
function castlePage() {return floorplan()+livingWingOverview();}

function roomResidentPortrait(who){
 const name=state.characterCatalog[who]?.name||state.people[who]?.name||'Resident';
 return `<button class="room-resident-panel" data-action="conversation" aria-label="Talk with ${escapeHtml(name)}"><img class="room-resident-art" src="${assetUrl(residentPortraitId(who))}" alt="Portrait of ${escapeHtml(name)}" width="640" height="960"><span>Talk with ${escapeHtml(name)} →</span></button>`;
}
function roomPage() {
  if (state.selectedRoomId==='conservatory') return conservatoryPage();
  const id = state.selectedRoomId, room = state.rooms[id], present = Boolean(state.characterCatalog.mira&&state.residentAtCastle&&state.residentRoomId===id);
  return `${actionButton('castle','← Castle floor plan','back')}${state.headquartersView.catalogue[id]?`<button data-hq-room="${id}">Work in this room →</button>`:''}${heading('THE LIVING WING',room.name,room.purpose)}<div class="room-scene-layout ${present?'has-resident':''}"><div class="scene ${state.currentDayPhase}"><img class="scene-background" src="${assetUrl(id)}" alt="${room.name}, illustrated at eye level"><span class="scene-tag">${titleCase(state.currentDayPhase)} · Restored</span>${id==='common-room'&&state.resonancePoints>=6?'<div class="violet-glow"></div>':''}<div class="scene-caption"><p class="eyebrow">${present?'MIRA IS HERE':'A QUIET MOMENT'}</p><p>${present?'“Make yourself comfortable.”':'The castle keeps its own gentle company.'}</p></div></div>${present?roomResidentPortrait('mira'):''}</div>${room.illustrationIsRepresentative?'<p class="bottom-note">Representative interior study: this room’s actual beds, residents and furnishing effects are listed below. A room-specific accepted illustration can be imported.</p>':''}<button data-art-expand="${id}">View room illustration →</button>${roomFurnishingsPanel(id)}${publicRoomFittings(id)}<div class="room-actions">${!state.characterCatalog.mira?'':present?actionButton('conversation','Speak with Mira ↗','primary'):actionButton('conversation',state.residentAtCastle?'Visit Mira in the '+state.rooms[state.residentRoomId].name+' →':'Mira is away with the expedition')}${actionButton('review-room','Review this illustration')}</div><section class="panel"><div class="panel-header"><h3>A place for something lovely</h3><span class="badge">FREE STYLING</span></div><p>Fixed slot · ${id==='library'?'Table lamp':state.housingCatalog[id]?'Bed-end seat':'Central seating'}. Supplied furnishing choices. Their current effects are listed above.</p><div class="options">${room.furnishings.map(choice=>`<button class="option ${state.roomFurnishings[id]===choice?'selected':''}" data-furnishing="${choice}" aria-pressed="${state.roomFurnishings[id]===choice}">${state.furnishingNames[choice]}</button>`).join('')}</div></section><p class="bottom-note">${room.description}</p>${id==='library'?libraryIndexPanel()+utilityArtifactPanels('library'):''}${roomSpellPanel(id)}${roomResidentPanel(id)}${personalShelfPanel(id)}${roomArrangementPanel(id)}`;
}
function conversationPage() {
  if (!state.founderAtCastle || !state.residentAtCastle) return `${heading('AT A DISTANCE','Mira is at home','Your scholar is away on an expedition.')}<section class="panel"><p>You may inspect the household while away, but no magical communication link has been established. Return home for in-person conversation; Mira’s invitation will wait.</p><button data-view="expeditions" class="primary">Return to the expedition →</button></section>`;
  const room = state.residentRoomId;
  const conversationRoomName=state.rooms[room]?.name||state.headquartersView.catalogue[room]?.name||'Castle';
  return `${actionButton('back-room','← Return to the room','back')}${heading('AN UNHURRIED CONVERSATION','A moment with Mira',conversationRoomName+' · Conversation does not advance time')}<div class="conversation-layout"><figure class="conversation-character"><img src="${assetUrl(residentPortraitId('mira'))}" alt="Mira" width="640" height="960"></figure><div class="scene conversation-stage"><img class="scene-background" src="${assetUrl(room)}" alt="${escapeHtml(conversationRoomName)}"><section class="dialogue-panel"><p class="eyebrow">MIRA · ARCHIVIST · AGE ${state.people.mira.adultAgeYears}</p><h2>Stay a little.</h2><span class="badge rose">ARCHIVIST · SCRIPTED & OPTIONAL GENERATED DIALOGUE</span><div class="dialogue-history" aria-live="polite">${state.conversation.length?state.conversation.map(line=>`<div class="speech ${line.speaker==='You'?'you':''}"><small>${escapeHtml(line.speaker)}${line.source==='generated'?' · generated reply':''}</small><p>${escapeHtml(line.text)}</p></div>`).join(''):'<div class="speech"><p>She leaves a finger between the pages and glances up. “I was just deciding whether this book or the company would be more interesting.”</p></div>'}</div><div class="dialogue-choices"><button data-topic="home">Ask about home</button><button data-topic="research">Talk about research</button><button data-topic="flirt">A little flirtation</button></div><form class="message-form" id="message-form"><input id="dialogue-message" name="message" aria-label="Your dialogue line" placeholder="Write a line…" maxlength="600" required autocomplete="off"><button aria-label="Save dialogue line">↗</button></form><small style="font-size:9px;margin-top:5px">Save a line without generation, or request a separate NPC draft below.</small></section></div></div>${residentMomentsPanel('mira')}${dialoguePanel()}${householdInvitationPanel()}`;
}
function householdPage() {
  return `<section class="panel"><h2>Invitations & personal style</h2><p>Reviewed conversations, shared memories and configurable clothing from your content pack.</p><button data-view="householdContent">Open household life →</button></section>${heading('THE PEOPLE WHO MAKE IT HOME','Your household','Open a resident’s sheet to talk, assign work or review their progress.',(Object.keys(state.characterCatalog).length-1)+' RESIDENTS')}<button data-view="householdWork">Household work & field companions →</button>${householdLifeOverview()}${toolInvitations()}${visitorsPanel()}${residentMomentsPanel()}<div class="portrait-layout"><div class="wardrobe-portrait"><img src="${assetUrl(portraitId())}" alt="Full figure portrait of Mira"><span class="badge">DEMONSTRATION CHARACTER</span></div><div><p class="eyebrow">ARCHIVIST · ${escapeHtml(state.people.mira.ancestryLabel)} · ${state.people.mira.adultAgeYears}</p><h2>Mira</h2><p>A collector of overlooked stories with a dry wit and a weakness for comfortable corners. She hopes to restore an archive worth getting lost in.</p><section class="panel"><h3>Life in the household</h3><p><strong>Primary interest:</strong> magical archives<br><strong>Training interest:</strong> protective wards<br><strong>Downtime:</strong> tea and terrible poetry</p></section><section class="panel"><h3>Between you</h3><p>${state.relationshipDescription}.</p><small>Shared moments now develop trust, affection and respect. Review their history on the character sheet.</small></section><div class="room-actions">${actionButton('conversation','Spend a moment ↗','primary')}${actionButton('wardrobe','Her wardrobe')}<button data-character="mira">Character build →</button></div>${householdInvitationPanel()}${additionalResidentCards()}${assignmentPanel()}<p class="bottom-note">Mira’s prototype styling choices are offered with her agreement. She is not a stand-in for Eris or Selene.</p></div></div>`;
}
function legacyWardrobePage() {
  return `${state.characterCatalog.tamsin?'<section class="panel"><h3>Tamsin’s clothing & saved styles</h3><button data-view="contacts">Visit her wardrobe and personal moments →</button></section>':''}${heading('PERSONAL EXPRESSION','Mira’s wardrobe','Choose Mira’s outfit and save a style you want to use again.','NO PHASE COST')}<div class="portrait-layout"><div class="wardrobe-portrait"><img src="${assetUrl(portraitId())}" alt="Mira in her selected illustrated outfit"><span class="badge">${state.wardrobe.outerLayer==='none'?'THE ARCHIVIST':'STYLING DETAIL · SHAWL'}</span></div><div><p class="eyebrow">NAMED ENSEMBLE</p><h2>The archivist</h2><p>Teal dress, worn leather boots, and an old volume she insists she will put down shortly.</p><label class="form-label">Dress</label><button class="option selected full" disabled>Teal scholar’s dress · base garment</button><label class="form-label">Outer layer</label><div class="options"><button class="option ${state.wardrobe.outerLayer==='none'?'selected':''}" data-layer="none" aria-pressed="${state.wardrobe.outerLayer==='none'}">No shawl</button><button class="option ${state.wardrobe.outerLayer==='plum-shawl'?'selected':''}" data-layer="plum-shawl" aria-pressed="${state.wardrobe.outerLayer==='plum-shawl'}">Plum shawl</button></div><section class="panel"><h3>Keep this styling</h3><p>Save a named combination to return to later.</p><form id="style-form" class="inline-form"><input name="styleName" aria-label="Saved style name" placeholder="e.g. Hearthside reading" maxlength="40" required><button class="primary">Save</button></form><div class="saved-styles">${state.savedStyles.map(style=>`<button data-style="${escapeHtml(style.name)}">${escapeHtml(style.name)} ↗</button>`).join('')}</div></section><p class="bottom-note">Saved garment details are descriptive. Portraits follow the three illustrated outfits below. Styling changes do not grant Resonance or change a character’s abilities.</p></div></div>`;
}
function residentPortraitId(who) {if(state.bathingOutfitView?.[who]?.active)return state.bathingOutfitView[who].portraitId;if(state.outfitProgressionView?.[who]?.portraitId)return state.outfitProgressionView[who].portraitId;if(who==='mira')return portraitId();if(state.companionLifeViews?.[who])return state.companionLifeViews[who].ensembles[state.companionLifeViews[who].ensembleId].portraitId;return who;}
function researchPage() {
  const completed = state.researchStatus==='complete';
  return `${heading('RESEARCH','At the research desk','Choose a lead, discover a principle, then put it to use.')}${friendshipCooperationPanel(['archive','archive-project'])}<div class="scene" style="aspect-ratio:2.5"><img class="scene-background" src="${assetUrl('library')}" alt="The castle research library"><div class="scene-caption"><p class="eyebrow">THE COLLECTIVE ARCHIVE</p><p>Study the wards that keep the hearth warm.</p></div></div><section class="panel"><div class="panel-header"><h2 style="margin:0">Understand the hearth wards</h2><span class="badge">${completed?'COMPLETE':state.researchStatus==='in-progress'?'IN PROGRESS':'AVAILABLE'}</span></div><p>Study the inscriptions that keep the hearth warm. This project costs 20 crowns once and needs three work phases. Each assigned researcher contributes one work unit per Advance; prepared Patient scholarship and an installed library index each add one. Existing rooms remain usable; this knowledge also unlocks practical living-wing improvements.</p><div class="stat-grid"><div class="stat"><small>One-time cost</small><strong>20 <small>crowns</small></strong></div><div class="stat"><small>Work completed</small><strong>${state.researchCompletedPhases} / 3</strong></div><div class="stat"><small>Shared funds</small><strong>${state.sharedFunds}</strong></div></div><div class="progress-track"><div class="progress-fill" style="width:${state.researchCompletedPhases/3*100}%"></div></div>${state.researchStatus==='not-started'?`<button class="primary" data-action="start-research" ${disabledAttrs(state.founderAtCastle&&state.sharedFunds>=20, [!state.founderAtCastle?'Return home to begin research.':'',state.sharedFunds<20?'Research needs 20 crowns. Copying commissions can earn the missing funds.':''])}>Begin research · 20 crowns</button>`:completed?'<p><strong>Recorded principle: steady hearth wards.</strong> This discovery is now in the household journal.</p>':`<p>Work resolves only for assigned characters. Your scholar: ${escapeHtml(state.founderAssignment)}${state.characterCatalog.mira?'; Mira: '+escapeHtml(state.residentAssignment):''}.</p>${assignmentPanel()}`}</section>${fieldcraftJourney()}${researchCataloguePanel()}${principleNotebook()}`;
}
function resonancePage() {
 const furnished=state.roomFurnishings['common-room']==='velvet-settee';
 const contributors=Object.entries(state.characterCatalog).filter(([who])=>who!=='founder'&&((who==='mira'&&state.completedDevelopments.includes('shared-flirtation'))||(who==='tamsin'&&state.additionalResidents.tamsin?.sharedFlirtation)||(state.romance?.people?.[who]?.mode==='open'&&state.romance.people[who].level>=1)));
 return heading('CASTLE RESONANCE','Resonance','The castle responds to established mutual affection. Only Advance adds passive Resonance.')+`<section class="panel"><h2>${state.resonancePoints} accumulated Resonance</h2><p>Next Advance: +${state.resonancePerPhase}. Each established mutual flirtation or open romantic relationship contributes 1, up to 3 per phase, while the plum settee is placed in the common room. Each person counts once.</p><p>Current contributors: ${contributors.map(([id,p])=>portraitImage(id)+' '+escapeHtml(p.name)).join(', ')||'none'}.</p><p>Plum settee: ${furnished?'placed':'not placed'}. You can change the furnishing in the common room.</p><button data-room="common-room">Open common room →</button><p>At 6 points the common room gains violet hearthlight. At 12 points, the repaired library lamp supports the optional Resonance lens study. Accumulated points are kept; the study does not spend them. Repeating affectionate scenes is unnecessary.</p><p>Ordinary restoration, recruitment and castle-history investigations remain available without romance or Resonance.</p><button data-view="mystery">Investigate the castle’s history →</button></section>`+castleLampPanel();
}

function journalDraftPanel() {
  const draft=dialogueDraft?.purpose==='journal'?dialogueDraft:null;
  const recent=recentDialogueDrafts.filter(item=>item.purpose==='journal');
  const results=draft?.sourceResults||state.lastPhaseSummary;
  return `<section class="panel"><p class="eyebrow">PHASE ACCOUNT · REVIEW BEFORE SAVING</p><h3>An account of the last Advance</h3>${dialogueRequest&&dialogueRequest.purpose!=='journal'?'<p>An NPC request is pending. Put its preview aside to request a journal account.</p>':''}<p>Create an account from the exact results of the last Advance. No model or provider is needed. Saving the account cannot change rewards, relationships or time.</p><details><summary>Events from the last Advance</summary><ul>${results.map(line=>`<li>${escapeHtml(line)}</li>`).join('')}</ul></details><label class="form-label" for="journal-draft-brief">Editorial brief</label><textarea id="journal-draft-brief" maxlength="600">Write a short, understated account of these resolved events.</textarea><button data-action="draft-dialogue" ${disabledAttrs(!dialogueRequest&&results.length, dialogueRequest?'Resolve or put aside the pending draft first.':'Advance once to create resolved events for this account.')}>Prepare phase account</button><button data-action="recover-dialogue">Recover journal drafts</button>${recent.map(item=>`<button data-draft-open="${item.id}">${escapeHtml(item.userText.slice(0,45))} · ${escapeHtml(item.status)}</button>`).join('')}${dialogueRequest?'<button data-action="retry-dialogue">Check / retry the same request</button><button data-action="discard-dialogue">Put preview aside / start fresh</button>':''}${draft?`<div class="dialogue-draft"><p>${escapeHtml(draft.status)} · ${escapeHtml(draft.model)}</p><blockquote>${escapeHtml(draft.text||'')}</blockquote>${draft.error?`<p role="alert">${escapeHtml(draft.error)}</p>`:''}${draft.status==='processing'?'<p>Request recorded. Check again for the saved result. After a server restart, a fresh request may incur additional provider usage.</p>':''}<p>Reported tokens: ${draft.usage?.total_tokens??'not supplied'}.</p>${draft.status==='ready'?`<button data-action="accept-dialogue" ${disabledAttrs(state.revision===draft.baseRevision, 'The campaign changed after this draft. Request a fresh draft before accepting.')}>Save reviewed journal account</button>${state.revision!==draft.baseRevision?'<p>The campaign changed. Generate a fresh draft.</p>':''}`:''}</div>`:''}</section>`;
}
function journalPage() {
  return `${heading('CAMPAIGN HISTORY','The household journal','Completed actions, discoveries and conversations, in date order.')}${state.soloLifeView.arrival?'<section class="panel"><button data-view="arrival">Your arrival & getting-settled guide →</button></section>':''}${journalDraftPanel()}<section class="panel" style="margin-top:0">${[...state.journal].reverse().map(entry=>`<article class="journal-entry"><small>DAY ${entry.dayNumber}<br>${entry.phase.toUpperCase()}</small><p>${entry.source==='generated'?'<strong>Reviewed generated account</strong><br>':''}${escapeHtml(entry.text)}</p>${entry.sourceResults?`<details><summary>Events from the last Advance</summary><ul>${entry.sourceResults.map(line=>`<li>${escapeHtml(line)}</li>`).join('')}</ul></details>`:''}</article>`).join('')}</section>`;
}
function reviewPage() {
  const labels = {...Object.fromEntries(Object.entries(state.headquartersView.catalogue).map(([id,d])=>[id,d.name])),...Object.fromEntries(Object.entries(state.containmentView.chambers).map(([id,d])=>[id,d.name])),...Object.fromEntries(Object.entries(state.publicWorkshopView.items).map(([id,o])=>['public-'+id,o.name+' · owned object'])),...Object.fromEntries(Object.entries(state.reviewedCandidates).map(([id,c])=>[id,c.profile.name+' · reviewed visitor'])),'aurelia':'Aurelia · lantern conservator','neris':'Neris · glassworker','iona':'Iona · surveyor’s work clothes','mira':'Mira · teal dress','tamsin':'Tamsin · work clothes','rainward-observatory':'Rainward observatory',...Object.fromEntries(Object.entries(state.rooms).map(([id,room])=>[id,room.name]))};
  return `${heading('KEEP THE PERSON. CORRECT THE PICTURE.','Illustration review','Compare a proposed image before accepting it.','OUTSIDE GAME TIME')}<label class="form-label" for="review-asset">Illustration</label><select id="review-asset">${Object.keys(state.originalAssets).map(id=>`<option value="${id}" ${reviewAssetId===id?'selected':''}>${escapeHtml(labels[id]||id.replaceAll('-',' '))}</option>`).join('')}</select><div class="review-comparison"><div><p class="review-label">ACCEPTED VERSION</p><div class="review-image"><img src="${assetUrl(reviewAssetId)}" alt="Currently accepted artwork"></div></div><div><p class="review-label">PROPOSED REVISION</p><div class="review-image">${proposedArtwork?`<img src="${proposedArtwork.url}" alt="Proposed replacement artwork">`:'<p>Import a corrected image to compare it here.<br>The accepted version stays in place.</p>'}</div></div></div><section class="panel"><label class="form-label" for="art-upload">Import corrected artwork · PNG, JPEG, or WebP · up to 6 MB</label><input type="file" id="art-upload" accept="image/png,image/jpeg,image/webp"><div class="room-actions"><button class="primary" data-action="accept-art" ${disabledAttrs(proposedArtwork, 'Choose a proposed illustration to review first.')}>Accept revision</button><button data-action="discard-art" ${disabledAttrs(proposedArtwork, 'Choose a proposed illustration to review first.')}>Discard preview</button><button data-action="rollback-art" ${disabledAttrs(state.assetHistory[reviewAssetId]?.length, 'There is no earlier accepted illustration to restore.')}>Restore previous version</button></div><p style="margin-top:15px">Images are versioned separately from character facts, room furnishings, and time. Transparent portraits work best.</p></section><section class="panel"><h3>Record a correction request</h3><form id="correction-form"><textarea name="note" aria-label="What should be corrected?" maxlength="600" required placeholder="Describe what should change and what must stay the same…"></textarea><button style="margin-top:10px">Save request</button></form><p style="margin-top:12px">${state.correctionRequests.length} request(s) recorded. Generate corrections externally, then import them above; founder portrait generation is available under Your character.</p></section>`;
}
function settingsPage() {
  return `${heading('YOUR CASTLE, YOUR SERVER','Settings & artwork','Independent solo saves on your own server.')} <section class="panel"><button data-view="campaigns">New game & saved campaigns →</button><button data-view="review">Illustration review →</button><button data-view="characterSetup">Your character →</button></section><details class="panel"><summary>Content packs</summary>${contentPackPanel()}${expansionPanel()}</details><details class="panel"><summary>Optional text generation</summary>${providerPanel()}</details><section class="panel"><h3>Optional portrait generation</h3>${portraitConfigPanel()}</section><section class="panel" style="margin-top:0"><h3>Saved where the game lives</h3><p>The JSON export is a visible-state diagnostic with undiscovered lore removed. Use the complete save backup to restore a campaign; it includes hidden story records and may contain spoilers if inspected.</p><p>Your campaign is stored in SQLite on the host, not in this browser. Reloading restores the same phase, furnishings, wardrobe, conversations, research, and accepted artwork.</p><div class="room-actions"><a href="${campaignUrl('/api/backup')}" download="stonework-and-spellcraft-save.zip">Download restorable save & artwork ↓</a></div><a href="${campaignUrl('/api/export')}" download="stonework-and-spellcraft-campaign.json">Download a readable campaign snapshot ↓</a><p style="margin-top:13px">The JSON snapshot is for inspection. The save ZIP contains a consistent database snapshot, accepted artwork, rollback images and restore instructions. Restore with the server stopped. Back up the entire data directory to preserve all campaign slots together.</p></section><details class="panel"><summary>About this build · ${APP_VERSION}</summary><p>Nine connected chapters cover settling in, castle development, household defenses, enchanting equipment, trade, patrols, defending the supply route and surveying the upper rooms. The optional castle investigation opens the Foundation Ritual Chamber. Shared provisions support daily life from the beginning. Personal stories, expeditions, and signature projects can continue beyond their chapters.</p><p>Scripted play runs locally without an external service. Optional text and portrait generation are configured separately.</p></details><section class="panel"><h3>Hosting</h3><p>Run <code>python server.py</code> or <code>docker compose up --build -d</code>. The included README covers host binding, persistence, backup, and private reverse-proxy access.</p><p>This private-server prototype has no built-in sign-in. Campaign slots separate game state, not user permissions. The supplied configuration listens locally; use an authenticated proxy or trusted private network for access from other machines.</p></section><p class="footer-line">STONEWORK AND SPELLCRAFT · DEVELOPMENT ${APP_VERSION} · SOURCE INCLUDED</p>`;
}
function systemPageContent() {
  if(currentView==='magicReference')return magicReferencePage();
  if(currentView==='bestiary')return bestiaryPage();
  if(currentView==='bounties')return bountyPage();
  if(currentView==='fullWorkshop')return workshopPage();
  if(SYSTEM_GROUPS[currentView])return systemHub(currentView);
  if(currentView==='goals')return heading('YOUR OWN DIRECTION','Goals','Pin up to three goals to see their next requirement and where to complete it.')+goalsPanel();
  if(currentView==='phaseTasks')return heading('YOUR NEXT CHOICES','This phase','Available tasks, paused work and invitations. Only Advance moves time.')+phasePlanPanel()+phaseTaskBoard();
  if(currentView==='householdWork')return householdWorkPage();
  if(currentView==='help')return helpPage();
  if(currentView==='cheats')return cheatsPage();
  if(currentView==='campaigns')return heading('AT YOUR DESK','New game & saves','Create a new campaign or continue an existing save.')+campaignPanel();
  if(state.startType==='fresh'&&currentView==='castle')return freshHome();
  if(state.startType==='fresh'&&currentView==='research'&&state.researchStatus!=='complete')return firstResearch();
  if(state.startType==='fresh'&&currentView==='workshop'&&!firstLanternMade())return firstCraft();
  if(!state.characterCatalog.mira&&['household','conversation'].includes(currentView))return soloHousehold();
  return ({firstPatrol:patrolPage,roadsWeKeep:roadsPage,workingTools:equipmentPage,armoury:armouryPage,armsOfOurOwn:armsPage,keepingHearth:keepingHearthPage,roomToGrow:roomToGrowPage,houseShape:houseShapePage,householdChapters:householdChaptersPage,workArrangements:workArrangementsPage,livingStories:livingStoriesPage,specialists:specialistsPage,progression:progressionPage,castleChapter:castleChapterPage,headquarters:headquartersPage,hqRoom:headquartersRoomPage,publicWorkshop:publicWorkshopPage,equipment:armouryPage,householdContent:householdContentPage,localEncounters:localEncountersPage,stories:personalStoriesPage,containment:containmentPage,mystery:mysteryPage,candidateReview:candidateProposalPage,companion:companionPage,castle:castlePage,ledger:ledgerPage,workroom:workroomPage,housing:housingPage,development:developmentPage,focus:focusPage,room:roomPage,contacts:contactsPage,household:householdPage,conversation:conversationPage,wardrobe:wardrobePage,spells:spellsPage,rituals:()=>lastingRitualsPanel()+embeddedSection(ritualsPage()),summoning:summoningPage,research:researchPage,restoration:restorationPage,workshop:workshopPage,stores:storesPage,requests:requestsPage,expeditions:expeditionsPage,resonance:resonancePage,journal:journalPage,review:reviewPage,settings:settingsPage}[currentView]||castlePage)();
}
function setView(view, {resetBestiary=true,resetMagicReference=true}={}) {
  if(view==='magicReference'&&resetMagicReference)magicReferenceEntry=null;
  if(view==='bestiary'&&resetBestiary)bestiaryEntry=null;
  if(view==='archiveProject'){selectedCharacterId='mira';uiCharacterTab='quests';view='characterProfile';}
  viewScroll[currentView]=Number(window.scrollY)||0;
  if(uiRenderedContext)viewScroll[uiRenderedContext]=Number(window.scrollY)||0;
  navigationOpen = false;
  uiSearch = '';
  if(roomContext&&!roomAllowsView(roomContext,view))roomContext=null;
  currentView = view; render();
  if(view==='publicWorkshop'&&!publicCatalogue)loadPublicCatalogue();
  if(['settings','campaigns','start'].includes(view))loadCampaigns();
  if(view==='settings')loadProvider();
  if(view==='settings')loadPortraitConfig();
  if(view==='characterSetup'){reviewAssetId='founder';proposedArtwork=null;loadPortraitConfig();}
  if(view==='cheats'&&!publicCatalogue)loadPublicCatalogue();
  window.scrollTo({top:viewScroll[uiRenderedContext]||0,behavior:'instant'});
  document.querySelector('#main-content')?.focus?.({preventScroll:true});
}
async function visitResident() {
  if (!state.characterCatalog.mira) return setView('peopleHub');
  if (!state.residentAtCastle) return setView('expeditions');
  await commit({type:'select-room',roomId:state.residentRoomId},'',()=>{currentView='conversation';});
}
function advanceSummary() {
  const completed=state.soloLife.lastCompletions||[];
  document.querySelector('#advance-content').innerHTML=presentUI(`<p class="eyebrow">THE HOUSEHOLD MOVES ON</p><h2>Day ${state.dayNumber}, ${titleCase(state.currentDayPhase)}</h2>${completed.length?`<section class="panel"><h3>Finished this phase</h3>${completed.map(p=>`<p><strong>${escapeHtml(p.name)}</strong> · complete</p>`).join('')}</section>`:'<p>Your phase is saved. Assigned work and household routines are recorded below.</p>'}${phaseResultHighlights()}${!state.expedition&&state.lastExpeditionReport?.returnedDay===state.dayNumber&&state.lastExpeditionReport?.logbook?.returnedPhase===state.currentDayPhase?'<button data-return-report="yes">Review expedition return →</button>':''}${phaseArrivalNotice()}${state.phaseTasks.tasks.filter(t=>!t.dismissed&&t.group==='ready'&&t.action).slice(0,3).map(t=>`<div class="ui-completion-action"><p>${escapeHtml(t.detail)}</p><button data-completion-task="${escapeHtml(t.id)}">${escapeHtml(t.title)} →</button></div>`).join('')}<details><summary>All phase events & routine production (${state.lastPhaseSummary.length})</summary><ul class="phase-results">${state.lastPhaseSummary.map(line=>`<li>${escapeHtml(line)}</li>`).join('')}</ul></details><form method="dialog"><button class="primary full" style="margin-top:15px">Continue the day</button></form>`);
  document.querySelector('#advance-content').onclick=event=>{const b=event.target.closest?.('button');if(b?.dataset.returnReport){document.querySelector('#advance-dialog').close();navigateTarget({view:'expeditions',siteId:state.lastExpeditionReport.siteId});return;}if(b?.dataset.completionTask){document.querySelector('#advance-dialog').close();return commit({type:'phase-task-run',taskId:b.dataset.completionTask},'Task saved.');}};
  document.querySelector('#open-phase-tasks').onclick=()=>{document.querySelector('#advance-dialog').close();setView('phaseTasks');};
  document.querySelector('#advance-dialog').showModal();
}
