  if (action==='draft-dialogue') return requestDialogue();
  if (action==='retry-dialogue') return requestDialogue(true);
  if (action==='accept-dialogue') return acceptDialogue();
  if (action==='discard-dialogue') {dialogueDraft=null;dialogueRequest=null;return render();}
  if (action==='refresh-provider') return loadProvider();
  if (action==='refresh-campaigns') return loadCampaigns();
  if (action==='retry-campaign') return createCampaign();
  if (action==='help') {helpTopic=helpForScreen();helpQuery='';return setView('help');}
  if (action==='retry') return sendPending('Save confirmed.');
