 const key=state.assetOverrides?.[id]||state.originalAssets?.[id]?id:'castle-emblem';
 return `<img class="destination-art" src="${escapeHtml(assetUrl(key))}" alt="${escapeHtml(name)}" width="640" height="400" loading="lazy">`;
