async function loadCampaigns() {
  try {
    const response=await fetch('/api/campaigns',{cache:'no-store'});
    const result=await response.json();
    if(!response.ok) throw new Error(result.error||'Could not read the saved campaigns.');
    campaignRows=result.campaigns;campaignListError='';
  } catch(error) {campaignListError=error.message;}
  if(['settings','campaigns','start'].includes(currentView)) render();
}
async function createCampaign(name) {
  if(busy||pendingRequest) return toast('Confirm the pending save before creating a campaign.');
  campaignCreationRequest ||= {campaignId:'c-'+newRequestId(),name,mode:'solo',startType:document.querySelector('#new-start-type')?.value||'fresh',publicStarter:document.querySelector('#new-public-starter')?.value||null};
  busy=true;document.body.classList.add('busy');
  try {
    const response=await fetch('/api/campaigns',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(campaignCreationRequest)});
    const result=await response.json();
    if(!response.ok) {campaignCreationRequest=null;throw new Error(result.error||'Could not create the campaign.');}
    campaignCreationRequest=null;location.href='/?campaign='+encodeURIComponent(result.campaignId);
  } catch(error) {toast(campaignCreationRequest?'Connection interrupted. Retry creation safely; the same campaign identifier will be reused.':error.message);render();}
  finally {busy=false;document.body.classList.remove('busy');}
}
function campaignPanel() {
  return newGameForm()+savedCampaigns()+(currentView==='start'?'':`<details class="panel"><summary>Rename this campaign</summary><form id="rename-campaign-form" class="focus-name-form"><label for="campaign-name">Campaign name</label><input id="campaign-name" name="name" value="${escapeHtml(state.campaignName)}" maxlength="70" required><button>Save name</button></form></details>`);
}
function focusPage() {
  const who=selectedCharacterId, focus=state.focusViews[who], project=focus.project;
  const upgrade=focusDesignId==='capacity';
  const design=upgrade?{name:'Two-slot focus',requiredPrinciple:'reference-binding',requiredProperties:['vessel','vessel']}:state.focusInscriptionCatalog[focusDesignId];
  const cost=upgrade?18:6, phases=upgrade?3:2;
  const draft=focusComponentChoices[who+':'+focusDesignId]||{};
  const chosen=design.requiredProperties.map((property,index)=>{
    const candidates=Object.entries(state.materialCatalog).filter(([,item])=>item.properties.includes(property));
    const prior=draft[index?'secondComponent':'firstComponent'];
    return candidates.some(([id])=>id===prior)?prior:candidates.find(([id])=>state.materialInventory[id]>0)?.[0]||'';
  });
  const blockers=[];
  if(!focus.canAlter) blockers.push('Return home with this character to agree focus work or change preparation.');
  if(state.equipmentView.projects[who])blockers.push('Finish or cancel this owner’s working-tool inscription first.');
  if(project) blockers.push('Finish the current focus project first; its progress is kept while paused.');
  if(upgrade?focus.capacity===2:focus.inscriptions.includes(focusDesignId)) blockers.push('This improvement is already complete.');
  if(!focus.knownPrinciples.includes(design.requiredPrinciple)) blockers.push('The owner must personally understand '+state.principleNames[design.requiredPrinciple]+'.');
  if(state.sharedFunds<cost) blockers.push('Requires '+cost+' shared crowns.');
  for(const id of new Set(chosen)) if(!id||state.materialInventory[id]<chosen.filter(key=>key===id).length) blockers.push(id?'Need '+chosen.filter(key=>key===id).length+' '+state.materialCatalog[id].name+'.':'Supply a compatible material in both slots.');
  return `${heading('PERSONAL EQUIPMENT','Focus & equipment','Upgrade a personal focus and select its active inscriptions.','PERSONAL EQUIPMENT')}
    <button data-tool-owner="${escapeHtml(who)}">Personal working tools →</button><div class="recipe-tabs">${Object.entries(state.characterCatalog).map(([id,character])=>`<button data-focus-character="${id}" class="option ${id===who?'selected':''}">${escapeHtml(character.name)}</button>`).join('')}</div>
    <section class="panel"><p class="eyebrow">${escapeHtml(state.characterCatalog[who].name)}</p><h2>${escapeHtml(focus.name)}</h2><p>${focus.capacity} prepared slot(s) in each configuration. Learn any of the four inscriptions; prepare only those you want active. Household and expedition preparations are saved separately. Tools are personal and cannot be delivered as shared artifacts.</p><form id="rename-focus-form" class="focus-name-form"><label for="focus-name">Name this focus</label><input name="name" id="focus-name" value="${escapeHtml(focus.name)}" maxlength="40" required><button ${disabledAttrs(focus.canAlter, 'Return home and finish any focus work before changing this preparation.')}>Save name</button></form><p class="bottom-note">Residents offer these practical tool improvements. Clothing and portrait art are unchanged by equipment preparation.</p></section>
    <div class="two-columns">${['household','expedition'].map(context=>`<section class="panel"><h3>${titleCase(context)} configuration</h3><p>${focus[context+'Loadout'].length} / ${focus.capacity} slots prepared. Changes are free at home.</p>${focus.inscriptions.some(id=>(id==='field-case')===(context==='expedition'))?focus.inscriptions.filter(id=>(id==='field-case')===(context==='expedition')).map(id=>{const active=focus[context+'Loadout'].includes(id);return `<div class="focus-choice"><strong>${state.focusInscriptionCatalog[id].name}</strong><p>${state.focusInscriptionCatalog[id].benefit}</p><button data-focus-toggle="${id}" data-focus-context="${context}" ${disabledAttrs(focus.canAlter&&(active||focus[context+'Loadout'].length<focus.capacity), !focus.canAlter?'Return home and finish current focus work first.':'All focus slots are occupied. Put an inscription aside first.')}>${active?'Put aside':'Prepare'}</button></div>`}).join(''):'<p>Complete a compatible inscription below, then prepare it here. The preservation case is for expeditions; work inscriptions are for household use.</p>'}</section>`).join('')}</div>
    ${project?`<section class="panel"><p class="eyebrow">${state.characterSheets[who].assignment==='inscribing'?'INSCRIPTION UNDERWAY':'INSCRIPTION PAUSED'}</p><h3>${project.kind==='capacity'?'Two-slot focus':state.focusInscriptionCatalog[project.inscriptionId].name}</h3><p>${project.completedWorkPhases} / ${project.requiredWorkPhases} assigned phases complete. Components and crowns are already committed. One work phase per Advance; other work pauses.</p><button data-worker="${who}" data-worker-assignment="inscribing" ${disabledAttrs(focus.canAlter, 'Return home and finish any focus work before changing this preparation.')}>Resume focus work</button></section>`:''}
    <section class="panel"><h2>Develop the focus</h2><label for="focus-design">Inscription or improvement</label><select id="focus-design">${Object.entries(state.focusInscriptionCatalog).map(([id,item])=>`<option value="${id}" ${focusDesignId===id?'selected':''}>${escapeHtml(item.name)}</option>`).join('')}<option value="capacity" ${upgrade?'selected':''}>Expand to two prepared slots</option></select><p>${upgrade?'Adds a second slot to both saved configurations. Existing inscriptions remain.':design.benefit}</p><p>${cost} crowns + two selected components · ${phases} assigned phases. Explicit focus work may consume reserved materials, just like crafting. It grants no advancement and never starts automatically.</p>
    <form id="focus-work-form"><div class="two-columns">${design.requiredProperties.map((property,index)=>`<label for="focus-${index?'second':'first'}">${titleCase(property)} component<select id="focus-${index?'second':'first'}" name="${index?'secondComponent':'firstComponent'}">${chosen[index]?'':'<option value="" selected>Buy a compatible material</option>'}${Object.entries(state.materialCatalog).filter(([,item])=>item.properties.includes(property)).map(([id,item])=>`<option value="${id}" ${chosen[index]===id?'selected':''}>${escapeHtml(item.name)} · ${state.materialInventory[id]} owned</option>`).join('')}</select></label>`).join('')}</div>${blockers.length?`<ul>${blockers.map(line=>`<li>${line}</li>`).join('')}</ul>`:'<p class="work-status">Ready to commit components and assign the owner.</p>'}<button class="primary" ${disabledAttrs(!blockers.length, blockers)}>${upgrade?'Begin capacity work':'Begin inscription'} · ${cost} crowns</button></form><div class="room-actions"><button data-view="stores">Buy materials →</button><button data-character="${who}">Study a missing principle →</button></div></section>${assignmentPanel()}`;
}


async function loadProvider() {
  try {
    const response=await fetch('/api/provider',{cache:'no-store'});
    const result=await response.json();
    if(!response.ok) throw new Error(result.error||'Could not read provider settings.');
    providerInfo=result;
    if(['settings','campaigns','start'].includes(currentView)) render();
  } catch(error) {toast(error.message);}
}
async function saveProvider(fields) {
  if(busy||pendingRequest) return;
  busy=true;
  try {
    const response=await fetch('/api/provider',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:fields.get('enabled')==='on',model:fields.get('model'),format:fields.get('format'),endpoint:fields.get('endpoint'),authMode:fields.get('authMode'),tokenParameter:fields.get('tokenParameter'),maxOutputTokens:Number(fields.get('maxOutputTokens')),apiKey:fields.get('apiKey'),removeApiKey:fields.get('removeApiKey')==='on'})});
    const result=await response.json();if(!response.ok) throw new Error(result.error||'Settings were not saved.');
    providerInfo=result;render();toast('Provider settings saved on this server. No request was sent to the model.');
  } catch(error) {toast(error.message);}
  finally {busy=false;}
}
function providerConnectionFields(c,kind){
 const text=kind==='text',prefix=text?'provider':'portrait';
 const formats=text?{openai:'OpenAI-compatible chat · OpenRouter, hosted or local',anthropic:'Anthropic Messages',gemini:'Google Gemini generateContent'}:{'openrouter-images':'OpenRouter chat image generation','openai-images':'OpenAI-compatible image generation · base64 response','gemini-images':'Google Gemini image generation'};
 return `<label for="${prefix}-format">API request format<select id="${prefix}-format" name="format">${Object.entries(formats).map(([id,label])=>`<option value="${id}" ${c.format===id?'selected':''}>${label}</option>`).join('')}</select></label><label for="${prefix}-endpoint">Complete API endpoint<input id="${prefix}-endpoint" name="endpoint" type="url" maxlength="1000" required value="${escapeHtml(c.endpoint||'https://openrouter.ai/api/v1/chat/completions')}"></label><p class="muted">Use the full request URL, including its path. Gemini endpoints can contain <code>{model}</code>; the saved model replaces it. Changing the endpoint or format clears the old key unless you enter a new one.</p><label for="${prefix}-auth">Authentication<select id="${prefix}-auth" name="authMode"><option value="key" ${c.authMode!=='none'?'selected':''}>API key</option><option value="none" ${c.authMode==='none'?'selected':''}>No authentication · local server</option></select></label>${text?`<label for="${prefix}-token">OpenAI-compatible output limit field<select id="${prefix}-token" name="tokenParameter"><option value="max_tokens" ${c.tokenParameter!=='max_completion_tokens'?'selected':''}>max_tokens · general compatibility</option><option value="max_completion_tokens" ${c.tokenParameter==='max_completion_tokens'?'selected':''}>max_completion_tokens · newer OpenAI models</option></select></label>`:''}<details><summary>Endpoint examples & compatibility</summary><ul><li>OpenRouter: <code>https://openrouter.ai/api/v1/chat/completions</code></li>${text?'<li>OpenAI: <code>https://api.openai.com/v1/chat/completions</code></li><li>Anthropic: <code>https://api.anthropic.com/v1/messages</code></li><li>Local compatible server: <code>http://localhost:1234/v1/chat/completions</code></li>':'<li>OpenAI images: <code>https://api.openai.com/v1/images/generations</code></li>'}<li>Gemini: <code>https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent</code></li></ul><p>Other providers work when they accept one of these request formats. Proprietary APIs require a compatible gateway. Enter a model available to your account. Saving does not send a request.</p></details>`;
}
function providerPanel() {
  const config=providerInfo;
  if(!config) return '<section class="panel"><h3>Optional reviewed text</h3><p>Loading server settings…</p><button data-action="refresh-provider">Load settings</button></section>';
  return `<section class="panel"><p class="eyebrow">OPTIONAL · SERVER-WIDE SETTINGS</p><h2>Optional AI text drafts</h2><p>Request a character reply, journal account or story draft, then review it. Replies use the character’s known facts and recent dialogue. Journal accounts use the event log. Spells are chosen directly from the Spellbook. It cannot change rules, resources, time or character abilities. Requests may incur provider charges. Scripted play remains available without a connection.</p><p>These settings apply to every campaign on this private server. Your key is stored on the server and excluded from campaign downloads. Keep access behind your trusted network or authenticated proxy.</p><form id="provider-form">${providerConnectionFields(config,"text")}<label for="provider-enabled"><input id="provider-enabled" name="enabled" type="checkbox" ${config.enabled?'checked':''}> Enable explicit text draft requests</label><label for="provider-model">Text model identifier</label><input id="provider-model" name="model" value="${escapeHtml(config.model)}" maxlength="150" placeholder="provider/model-id"><label for="provider-key">API key · ${config.hasApiKey?'stored; leave blank to retain':'not configured'}</label><input id="provider-key" name="apiKey" type="password" autocomplete="new-password" maxlength="500" value=""><label for="provider-remove-key"><input id="provider-remove-key" name="removeApiKey" type="checkbox"> Remove stored key (also disable drafts)</label><label for="provider-limit">Maximum output tokens per request</label><input id="provider-limit" name="maxOutputTokens" type="number" min="100" max="1500" value="${config.maxOutputTokens}" required><button class="primary">Save provider settings</button></form><p class="bottom-note">Use a chat-capable model available to your account. No model or price is assumed, and saving settings does not test or contact the provider. Founder portrait generation has separate settings under Your character. Chapters, recruitment, combat, progression and companion stories use local scripts. No AI gamemaster is needed.</p></section>`;
}
function dialogueCharacter() {return currentView==='summoning'?selectedSummoningPerson:currentView==='contacts'?'tamsin':'mira';}
function dialoguePanel() {
  const who=dialogueCharacter();
  const draft=dialogueDraft&&(dialogueDraft.purpose||'dialogue')==='dialogue'&&(dialogueDraft.characterId||'mira')===who?dialogueDraft:null;
  const recent=recentDialogueDrafts.filter(item=>(item.purpose||'dialogue')==='dialogue'&&(item.characterId||'mira')===who);
  return `<section class="panel"><p class="eyebrow">OPTIONAL GENERATED DIALOGUE</p><h3>A reply from ${escapeHtml(state.people[who]?.name||who)}</h3>${dialogueRequest&&(dialogueRequest.purpose==='journal'||(dialogueRequest.characterId||'mira')!==who)?'<p>A draft for another resident is pending. It stays saved for recovery.</p><button data-action="discard-dialogue">Put that preview aside</button>':''}<button data-action="recover-dialogue">Recover recent saved drafts</button>${recent.length?`<div class="room-actions">${recent.map(item=>`<button data-draft-open="${item.id}">${escapeHtml(item.userText.slice(0,45))} · ${item.status}</button>`).join('')}</div>`:''}<p>Type a line in the conversation input above, then request a draft. It is previewed here before either line enters the conversation. Configure the provider in Settings & artwork.</p><button data-action="draft-dialogue" ${disabledAttrs(!dialogueRequest, 'Resolve or put aside the pending draft first.')}>Request NPC reply draft</button>${dialogueRequest?'<button data-action="retry-dialogue">Check / retry the same request</button>':''}${draft?`<div class="dialogue-draft"><p><strong>${escapeHtml(draft.status)} · ${escapeHtml(draft.model||'')}</strong></p><p>Your line: ${escapeHtml(draft.userText||'')}</p>${draft.text?`<blockquote>${escapeHtml(draft.text)}</blockquote>`:''}${draft.error?`<p role="alert">${escapeHtml(draft.error)}</p>`:''}${draft.status==='processing'?'<p>Request recorded. Check again for its result. If the server restarted during generation, discard this draft before deliberately making a new request; the earlier request may have incurred usage.</p>':''}<p>Reported tokens: ${draft.usage?.total_tokens??'not supplied'}. No price estimate is inferred.</p>${draft.status==='ready'?`<button data-action="accept-dialogue" ${disabledAttrs(state.revision===draft.baseRevision, 'The campaign changed after this draft. Request a fresh draft before accepting.')}>Accept these two dialogue lines</button>${state.revision!==draft.baseRevision?'<p>The campaign changed. Discard and generate a fresh draft for the current scene.</p>':''}`:''}<button data-action="discard-dialogue">Discard preview / start fresh</button></div>`:''}</section>`;
}
async function requestDialogue(retry=false) {
  if(busy||pendingRequest) return;
  if(!retry) {
    const text=document.querySelector(currentView==='journal'?'#journal-draft-brief':'#dialogue-message')?.value?.trim();
    if(!text) return toast('Write a line or a journal brief first.');
    dialogueRequest={requestId:newRequestId(),expectedRevision:state.revision,text,...(currentView==='journal'?{purpose:'journal',source:'offline'}:{characterId:dialogueCharacter()})};
  }
  if(!dialogueRequest) return;
  busy=true;document.body.classList.add('busy');
  try {
    const response=await fetch(campaignUrl('/api/dialogue/draft'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(dialogueRequest)});
    const result=await response.json();
    if(!response.ok) {dialogueRequest=null;throw new Error(result.error||'Draft request failed.');}
    dialogueDraft=result;render();
  } catch(error) {render();toast(dialogueRequest?'Connection interrupted. Check the same request to recover its saved result without another provider call.':error.message);}
  finally {busy=false;document.body.classList.remove('busy');}
}
async function acceptDialogue() {
  if(busy||pendingRequest||!dialogueDraft) return;
  busy=true;document.body.classList.add('busy');
  try {
    const response=await fetch(campaignUrl('/api/dialogue/accept'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({draftId:dialogueDraft.id})});
    const result=await response.json();if(!response.ok) throw new Error(result.error||'Draft could not be accepted.');
    state=result;dialogueDraft=null;dialogueRequest=null;render();toast('Reviewed prose saved. No game time or resources changed.');
  } catch(error) {toast(error.message);}
  finally {busy=false;document.body.classList.remove('busy');}
}

async function recoverDialogue() {
  try {
    const response=await fetch(campaignUrl('/api/dialogue/drafts')+(currentView==='journal'?'&purpose=journal':'&purpose=dialogue&character='+dialogueCharacter()),{cache:'no-store'});
    const result=await response.json();if(!response.ok) throw new Error(result.error||'Could not recover drafts.');
    recentDialogueDrafts=result.drafts;render();
    if(!recentDialogueDrafts.length) toast('No saved drafts in this campaign yet.');
  } catch(error) {toast(error.message);}
}


