function spellComponents(properties, prefix, draft={}) {
  return properties.map((property,index)=>{
    const name=prefix==='spell-draft'?(index?'secondComponent':'firstComponent'):'component'+index;
    const candidates=Object.entries(state.materialCatalog).filter(([,item])=>item.properties.includes(property));
    const selected=candidates.some(([id])=>id===draft[name])?draft[name]:candidates.find(([id])=>state.materialInventory[id]>0)?.[0]||candidates[0][0];
    return `<label for="${prefix}-${index}">${titleCase(property)} component<select id="${prefix}-${index}" name="${name}">${candidates.map(([id,item])=>`<option value="${id}" ${id===selected?'selected':''}>${escapeHtml(item.name)} · ${state.materialInventory[id]} owned</option>`).join('')}</select></label>`;
  }).join('');
}
