function ritualsPage() {
  if(!state.characterCatalog.mira)return heading('WORK & STUDY','Rituals','Rituals combine the work of qualified participants over several assigned phases.')+'<section class="panel"><p>The concordant lesson belongs to Mira’s demonstration story. Other shared rituals are available in the content workshop, with their own knowledge and participant requirements.</p><button data-view="publicWorkshop">Explore shared workings →</button></section>';
  const ritual=state.spellRitual, blockers=[...state.spellRitualBlockers];
  const materials=['vessel','binding','vessel','binding'].map((property,index)=>{
    const candidates=Object.entries(state.materialCatalog).filter(([,item])=>item.properties.includes(property));
    return ritualDraft['component'+index]||candidates.find(([id])=>state.materialInventory[id]>0)?.[0]||candidates[0][0];
  });
  for(const id of new Set(materials)) {
    const count=materials.filter(key=>key===id).length;
    if(state.materialInventory[id]<count) blockers.push('Need '+count+' '+state.materialCatalog[id].name+' across the selected ritual slots; '+state.materialInventory[id]+' owned.');
  }
  return `${heading('GROUP RITUALS','Rituals','Select participants, supply the materials and assign the ritual work.')}
  <section class="panel"><p class="eyebrow">ONE-TIME HOUSEHOLD RITUAL</p><h2>The concordant lesson</h2><p>Two people use the living index to rehearse separate spell patterns without confusing them. Mira offers this memory exercise with your scholar. It changes neither personality nor relationships.</p><p><strong>Lasting effect:</strong> each participant gains three base personal spell slots instead of two, plus any active personal blessing. Existing preparation stays as chosen. No upkeep, expiry or repeat funding.</p><p><strong>Requirements:</strong> both participants know Reference binding; at least one knows Clear instruction; the living index charm is installed. Both must be at home.</p><p><strong>Cost:</strong> 18 shared crowns and four components: a vessel and a binding component per participant. Two coordinated Advance phases, with both participants assigned to this ritual. Switching either person to other work pauses the shared ritual.</p>
  <div class="two-columns">${Object.entries(state.characterCatalog).filter(([id])=>['founder','mira'].includes(id)).map(([id,person])=>`<div class="work-card"><h3>${escapeHtml(person.name)}</h3><p>${ritual.contributions[id]} / 2 contributions</p><p>${state.characterSheets[id].atCastle?'At home':'Away'} · ${state.characterSheets[id].assignment==='ritual'?'Assigned to this ritual':'Other plans'}</p></div>`).join('')}</div>
  ${ritual.status==='complete'?'<p class="work-status">Completed. Both participants have three base preparation slots, plus any active personal blessing.</p>':ritual.status==='in-progress'?`<p>Paid components and contributions are retained while paused.</p><button class="primary" data-ritual-resume="concordant-lesson" ${disabledAttrs(state.founderAtCastle&&state.residentAtCastle, 'Your scholar and Mira must both be at home.')}>Assign both participants & resume</button>`:`<ul>${blockers.map(line=>`<li>${escapeHtml(line)}</li>`).join('')}</ul><form id="spell-ritual-form"><div class="two-columns">${spellComponents(['vessel','binding','vessel','binding'],'ritual',ritualDraft)}</div><p>Stock is validated together before payment. Reusing a material in two slots needs two copies; explicit ritual work may use reserved stock.</p><button class="primary" ${disabledAttrs(!blockers.length, blockers)}>Begin together · 18 crowns</button></form>`}<div class="room-actions"><button data-view="spells">Open spellbook →</button><button data-view="stores">Buy components →</button><button data-view="development">Check personal knowledge →</button></div></section>${assignmentPanel()}`;
}

