function personalStoriesPage() {
 const v=state.personalStoryView;
 if(!Object.keys(v.owners).length)return heading('PEOPLE','Personal stories','A resident’s interests will open their own stories after you meet.')+'<button data-view="localEncounters">Meet someone nearby →</button>';
 if(!v.owners[storyOwnerId])storyOwnerId=Object.keys(v.owners)[0];
 const owner=v.owners[storyOwnerId],draft=storyProposal,p=draft?.proposal,r=draft?.ruleReview;
 const materials=items=>Object.entries(items).map(([key,count])=>`${count} ${escapeHtml(state.materialCatalog[key].name)}`).join(' + ');
 const costs=r=>`${r.costCrowns} shared crowns + ${materials(r.materials)}; ${r.requiredWorkPhases} base work phases; ${r.advancement} one-time personal advancement${r.principle?' and knowledge of '+escapeHtml(state.principleNames[r.principle]):''}.`;
 const button=(key,action,label,enabled=true)=>`<button data-story-action="${action}" data-story-id="${key}" ${enabled?'':'disabled'}>${label}</button>`;
 return `${heading('AMBITIONS WITH A LIFE AFTER ARRIVAL','Personal stories','Choose a resident’s story, review its project costs and continue its available scenes.')}<section class="panel">${Object.entries(v.owners).map(([who,o])=>`<button data-story-owner="${who}" aria-pressed="${who===storyOwnerId}">${escapeHtml(o.name)}</button>`).join('')}<h2>${escapeHtml(owner.name)}’s next chapter</h2><p>Choose a prepared story that develops her ambition. Optional model-written prose is also available. Approval creates an unfunded offer. Funding uses her current task; only Advance performs work. Each package can be completed once per person. Sharing a completed follow-up unlocks A shared revision; completing and sharing that chapter unlocks A collected working method. Enduring focus adds one story work point per assigned phase. Projects never buy affection, obedience or Resonance.</p>${owner.requestBlockers.map(escapeHtml).join(' ')}<label>Personal story <select id="story-package">${Object.entries(owner.packages).map(([key,d])=>`<option value="${key}">${escapeHtml(d.name)}</option>`).join('')}</select></label><label>Brief for model-written story<textarea id="story-brief" maxlength="600" placeholder="Build on her interests and what she has already accomplished…"></textarea></label><button data-story-draft="offline" ${disabledAttrs(!owner.requestBlockers.length&&!storyProposalRequest,[...owner.requestBlockers,storyProposalRequest?'Resolve or put aside the pending story proposal.':''])}>Prepare this personal story</button><button data-story-draft="new" ${disabledAttrs(!owner.requestBlockers.length&&!storyProposalRequest,[...owner.requestBlockers,storyProposalRequest?'Resolve or put aside the pending story proposal.':''])}>Request model-written story</button><button data-story-draft="recover">Recover saved proposals</button>${storyProposalRequest?'<button data-story-draft="retry">Check same request</button>':''}<button data-story-draft="discard">Put preview aside</button>${recentStoryProposals.map(d=>`<button data-story-draft-open="${d.id}">${escapeHtml(d.proposal?.title||d.userText)} · ${escapeHtml(d.status)}</button>`).join('')}</section>${draft?`<section class="panel"><p>${escapeHtml(draft.status)} · ${escapeHtml(draft.model)}</p>${draft.error?`<p role="alert">${escapeHtml(draft.error)}</p>`:''}${p&&r?`<h2>${escapeHtml(p.title)}</h2><p>${escapeHtml(p.premise)}</p><blockquote>${escapeHtml(p.invitation)}</blockquote><p>${escapeHtml(p.proposedWork)}</p><p><strong>Exact rules:</strong> ${costs(r)}</p><details><summary>Preview eventual completion and optional scene · not yet happened</summary><p>${escapeHtml(p.completion)}</p><p>${escapeHtml(p.followupInvitation)}</p><blockquote>${escapeHtml(p.followupScene)}</blockquote></details>${draft.status==='ready'?`<label><input id="story-content-reviewed" type="checkbox"> I reviewed the story, continuity and her independent preferences.</label><label><input id="story-mechanics-reviewed" type="checkbox"> I reviewed the exact costs, work and rewards.</label><button data-story-draft="approve" ${disabledAttrs(draft.baseRevision===state.revision, 'The campaign changed after this draft. Request a fresh draft before accepting.')}>Approve unfunded offer</button><button data-story-draft="recheck">Recheck against current save · no provider call</button>`:''}`:''}</section>`:''}${Object.entries(v.stories).filter(([,r])=>r.ownerId===storyOwnerId).map(([key,r])=>`<section class="panel"><p class="eyebrow">${escapeHtml(r.status)} · ${escapeHtml(r.source)}</p><h2>${escapeHtml(r.proposal.title)}</h2><p>${escapeHtml(r.proposal.premise)}</p><p>${escapeHtml(r.proposal.proposedWork)}</p><p>${costs(r.rules)}</p>${r.status==='offered'?`<blockquote>${escapeHtml(r.proposal.invitation)}</blockquote>${r.startBlockers.map(line=>`<small>${escapeHtml(line)}</small>`).join('')}${button(key,'start-personal-story','Agree & fund her work',!r.startBlockers.length)}${button(key,'defer-personal-story','Put offer aside',r.present)}`:r.status==='deferred'?button(key,'restore-personal-story','Restore offer',r.present):r.status==='in-progress'?`<p>${r.completedWorkPhases} / ${r.rules.requiredWorkPhases} work · ${r.workPerPhase} contribution per assigned phase · ${r.working?'working':'paused'}.</p>${button(key,'resume-personal-story','Resume her work',r.present)}<button data-story-pause="${r.ownerId}" ${disabledAttrs(r.present, 'All participants must be present at home.')}>Pause · keep progress</button>${button(key,'cancel-personal-story','Cancel unfinished work & refund',r.present)}`:`<p>${escapeHtml(r.proposal.completion)}</p>${r.sceneStatus==='remembered'?`<blockquote>${escapeHtml(r.proposal.followupScene)}</blockquote><small>Remembered day ${r.sceneOn.dayNumber}, ${escapeHtml(r.sceneOn.phase)}.</small>`:`<p>${escapeHtml(r.proposal.followupInvitation)}</p>${r.sceneStatus==='waiting'?button(key,'join-story-scene','Join her · no time or rewards',r.canJoin)+button(key,'defer-story-scene','Put invitation aside',r.present):button(key,'restore-story-scene','Restore invitation',r.present)}`}`}</section>`).join('')}`;
}
async function storyDraftAction(action) {
 if(busy||pendingRequest)return;
 if(action==='discard'){storyProposal=null;storyProposalRequest=null;return render();}
 let path,payload;
 if(action==='recover')path=campaignUrl('/api/dialogue/drafts')+'&purpose=story-proposal&owner='+encodeURIComponent(storyOwnerId);
 else if(action==='approve'){
  if(!storyProposal)return;
  payload={draftId:storyProposal.id,contentReviewed:document.querySelector('#story-content-reviewed')?.checked===true,mechanicsReviewed:document.querySelector('#story-mechanics-reviewed')?.checked===true};
  if(!payload.contentReviewed||!payload.mechanicsReviewed)return toast('Read and confirm both review statements.');
  path=campaignUrl('/api/dialogue/accept');
 }else if(action==='recheck'){
  if(!storyProposal)return;
  path=campaignUrl('/api/story/review');payload={draftId:storyProposal.id,expectedRevision:state.revision};
 }else{
  if(action==='new'||action==='offline'){
   if(storyProposalRequest)return;
   const text=document.querySelector('#story-brief')?.value?.trim()||'Build on her own ambition and completed work.';
   storyProposalRequest={requestId:newRequestId(),purpose:'story-proposal',ownerId:storyOwnerId,source:action==='offline'?'offline':'provider',packageId:document.querySelector('#story-package')?.value,expectedRevision:state.revision,text};
  }
  if(!storyProposalRequest)return;
  path=campaignUrl('/api/dialogue/draft');payload=storyProposalRequest;
 }
 busy=true;document.body.classList.add('busy');
 try{
  const response=await fetch(path,payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{cache:'no-store'});
  const result=await response.json();if(!response.ok)throw new Error(result.error||'Story review failed.');
  if(action==='recover')recentStoryProposals=result.drafts.filter(d=>d.purpose==='story-proposal'&&d.ownerId===storyOwnerId);
  else if(action==='approve'){state=result;storyProposal=null;storyProposalRequest=null;}
  else storyProposal=result;
  render();
 }catch(error){toast(error.message);}finally{busy=false;document.body.classList.remove('busy');}
}

function arrivalPathPanel(who) {
 const v=state.arrivalPathViews[who],p=v.project,home=state.founderAtCastle;
 const button=(kind,label,enabled=true,extra='')=>`<button data-arrival-path-action="${kind}" data-arrival-person="${who}" ${extra} ${disabledAttrs(enabled&&home,!home?'Return your scholar to the castle.':v.startBlockers)}>${label}</button>`;
 if(v.arrivalMethod==='recruitment'){
  if(state.people[who])return '<section class="panel"><h3>Established contact</h3><p>Continue her saved correspondence below. Visits, accommodation and membership remain separate agreements.</p></section>';
  const quest=state.recruitmentView?.quests.find(q=>q.id===who),profile=state.characterCatalog[who];
  if(quest)return recruitmentPanel(who);
  return `<section class="panel"><h3>Meet through a quest</h3><p>Common residents live in the surrounding country. Follow a rescue lead, or locate a bandit and seek a voluntary agreement after capture and release.</p>${foodButton({type:'recruit-lead',characterId:who,questKind:'rescue'},'Follow a rescue lead',home?[]:['Return home first.'])}${profile?.identitySource!=='authored-local-encounter'&&profile?.ancestryLabel!=='Bovinefolk'?foodButton({type:'recruit-lead',characterId:who,questKind:'capture'},'Follow a bandit lead',home?[]:['Return home first.']):''}</section>`;
 }

 const body=v.body;
 return `<section class="panel"><h3>Construct & awaken · ${escapeHtml(body.name)}</h3><p>Four own scholar phases construct the adult body and animating focus; two more perform the awakening ritual. ${body.costCrowns} shared crowns + ${Object.entries(body.materials).map(([key,count])=>`${count} ${escapeHtml(state.materialCatalog[key].name)}`).join(' + ')}. Body materials are narrative and cost choices; they grant no hidden combat or work bonuses.</p><p>Personal understanding of Clear instruction and Gentle preservation is required. She awakens fully adult in form and cognition, with no fabricated lived years. No obedience, romance or household work is owed.</p>${p?.status==='complete'?'<p>She is awake. Her identity cannot be cancelled or rebuilt; discuss membership or departure below.</p>':p?.status==='in-progress'?`<p>${p.completedWorkPhases} / 6 phases · ${p.completedWorkPhases<4?'constructing body and focus':'awakening ritual'} · ${p.working?'assigned':'paused'}.</p>${button('resume-golem','Resume construction / ritual')}<button data-founder="rest" ${disabledAttrs(home, 'Everyone needed for this action must be at home.')}>Pause · preserve work</button>${button('cancel-golem','Cancel unawakened plan & refund')}<h4>Accommodation at awakening</h4><p>${p.roomId?'Planned: '+escapeHtml(state.rooms[p.roomId].name):'Choose a suitable free room.'} This plan does not reserve a bed. Final awakening waits safely if the bed is no longer free.</p>${v.eligibleRoomIds.map(room=>button('choose-golem-room','Plan '+escapeHtml(state.rooms[room].name),true,`data-arrival-room="${room}"`)).join('')}${!v.eligibleRoomIds.length?'<p>No suitable free bedroom. Restore or free a room before awakening can finish.</p>':''}<button data-view="housing">Rooms & beds →</button>`:`${v.startBlockers.map(line=>`<small>${escapeHtml(line)}</small>`).join('')}${button('start-golem','Fund body, focus & awakening',!v.startBlockers.length)}`}</section>`;
}

function localEncountersPage(){
 const v=state.localEncounterView,p=v.project;
 const button=(kind,label,key='',enabled=true)=>`<button data-local-encounter-action="${kind}" data-encounter-id="${key}" ${disabledAttrs(enabled&&state.founderAtCastle,key?v.encounters[key].startBlockers:['Return home before managing this appointment.'])}>${label}</button>`;
 return recruitmentPanel()+`${heading('NEIGHBOURS, TRAVELLERS & WORKSHOP LETTERS','Local introductions','Choose a nearby person to meet. A meeting does not reserve a bed or recruit them.')}<section class="panel"><p>These unique companions have persistent identities. Reviewed portraits appear where available; new portraits use placeholders. Ordinary meetings use no ritual materials. Zahra and Sylva require an exotic contact ritual after their letters are discovered. Studying a lead takes one assigned scholar phase, only on Advance. Common neighbours then need a rescue quest before an invitation; Koharu’s existing local workshop meeting and exotic contact rituals keep their own paths. Visits, beds and membership remain separate agreements.</p><button data-view="summoning">People & arrivals →</button><button data-view="expeditions">Beyond the walls →</button></section>${p?`<section class="panel"><h2>${escapeHtml(v.encounters[p.encounterId].place)}</h2><p>${v.working?'Appointment assigned':'Paused; invitation kept'}.</p>${button('resume-local-visit','Resume appointment')}<button data-founder="rest" ${disabledAttrs(state.founderAtCastle, 'Return your scholar to the castle first.')}>Pause</button>${button('cancel-local-visit','Put appointment aside')}</section>`:''}<div class="practice-grid">${Object.entries(v.encounters).map(([key,d])=>`<article class="panel"><img src="${assetUrl(key)}" alt="${escapeHtml(d.name)}, adult ${escapeHtml(d.ancestry)}" style="width:100%;max-height:420px;object-fit:contain"><p class="eyebrow">${escapeHtml(d.ancestry)} · ${d.age} · ${['zahra','sylva'].includes(key)?'EXOTIC CONTACT':key==='koharu'?'LOCAL WORKSHOP MEETING':'RESCUE LEAD'}</p><h2>${escapeHtml(d.name)}</h2><p>${escapeHtml(d.lead)}</p><p>${escapeHtml(d.ambition)}</p>${d.status==='introduced'?`<p>Introduction recorded day ${d.completedOn.dayNumber}. Her identity and any later choices are kept.</p><button data-summoning-candidate="${key}">Continue her correspondence →</button>`:`<p class="recruitment-status"><strong>${d.canStart?'Available now':'Not available yet'}</strong><br>${escapeHtml(d.startBlockers.join(' ')||d.unlock)}</p>${!d.unlocked?`<button ${['fenna','sylva','nyssara'].includes(key)?`data-site="${key==='nyssara'?'ridge-cistern':'fern-nursery'}"`:`data-view="${key==='zahra'?'restoration':'research'}"`}>${key==='nyssara'?'Survey Ridge cistern':['fenna','sylva'].includes(key)?'Explore the fern nursery':key==='zahra'?'Restore the conservatory':key==='elowen'?'Study the hearth wards':'Study Courteous passage'} →</button>`:''}${button('start-local-visit',key==='koharu'?'Arrange workshop meeting · 1 phase':'Study her route notes · 1 phase',key,d.canStart)}`}</article>`).join('')}</div>`;
}


const candidateEditableFields=[['name',40],['personality',400],['appearanceDescription',500],['origin',400],['ambition',300],['introduction',500],['personalTopic',500]];
function candidatePoolChoices() {
 const imported=document.querySelector('#pool-contentSource')?.value==='imported';
 const keys=imported?['ancestry','arrivalMethod','bodyMaterial']:['ancestry','background','temperament','story','arrivalMethod','bodyMaterial','hair','build'];
 return {...(imported?{contentSource:'imported'}:{}),...Object.fromEntries(keys.map(k=>[k,document.querySelector('#pool-'+k)?.value]).filter(([,v])=>v))};
}
function candidateIngredientPanel(draft) {
 const g=draft?.generationIngredients;if(!g)return '';
 if(g.contentSource!=='imported')return `<p>Pool version ${g.version} · ${escapeHtml(state.characterPool.backgrounds[g.background].name)} · ${escapeHtml(state.characterPool.temperaments[g.temperament].name)} · ${escapeHtml(state.characterPool.stories[g.story].name)}. These ingredients remain attached to her saved identity.</p>`;
 return `<details class="panel"><summary>Source ingredients · ${escapeHtml(g.pack.packId)} · ${escapeHtml(g.pack.packVersion)}</summary><p>Selected records are preserved with this identity. Clothing and interactions are not automatically applied. Compact prose can shorten long source descriptions; review the complete source here.</p>${Object.entries(g.records).map(([kind,record])=>`<details><summary>${escapeHtml(titleCase(kind))}: ${escapeHtml(record.label||record.title||record.name||record.id)}</summary>${recordFields(record)}</details>`).join('')}${g.ancestry==='Golem'?'<p>Appearance uses the selected construction material, since free-text appearances cannot be safely matched to a body material. Her age describes her adult form.</p>':''}</details>`;
}
function candidateEditor(draft) {
 return `<details class="panel"><summary>Revise this draft · no provider call</summary><p>Edit individual details before approval. Selected age, ancestry, occupation and starting package remain fixed. The original character details remain available for comparison. Approved edits become the character’s description.</p>${candidateEditableFields.map(([key,limit])=>`<label for="candidate-edit-${key}">${escapeHtml(titleCase(key.replace(/([A-Z])/g,' $1')))}</label><textarea id="candidate-edit-${key}" maxlength="${limit}">${escapeHtml(draft.proposal[key])}</textarea>`).join('')}<label for="candidate-edit-accommodationPreference">Accommodation</label><select id="candidate-edit-accommodationPreference">${['private-room','separate-bed'].map(v=>`<option value="${v}" ${draft.proposal.accommodationPreference===v?'selected':''}>${escapeHtml(titleCase(v))}</option>`).join('')}</select><label for="candidate-edit-stayPreference">Stay preference</label><select id="candidate-edit-stayPreference">${['visit-only','open-to-staying'].map(v=>`<option value="${v}" ${draft.proposal.stayPreference===v?'selected':''}>${escapeHtml(titleCase(v))}</option>`).join('')}</select><button data-candidate-draft="edit">Save revisions & recheck</button></details>`;
}
function recordFields(record) {
 const valueHtml=value=>value===null?'<span>Not specified</span>':Array.isArray(value)?(value.length?'<ul>'+value.map(v=>'<li>'+valueHtml(v)+'</li>').join('')+'</ul>':'<span>None</span>'):typeof value==='object'?recordFields(value):escapeHtml(String(value));
 return Object.entries(record).map(([key,value])=>`<div class="record-field"><strong>${escapeHtml(titleCase(key.replace(/([A-Z])/g,' $1')))}:</strong> ${valueHtml(value)}</div>`).join('');
}
function contentPackPanel() {
 const r=contentPackReport,p=contentPackPreview,active=state.activeContentPack;
 return `<section class="panel"><p class="eyebrow">CAMPAIGN CONTENT</p><h2>Character content packs</h2><p>${active?'Active: '+escapeHtml(active.packId)+' · '+escapeHtml(active.packVersion):'Built-in ingredients only.'} Existing residents and saved proposals keep their identities when packs change. Full save backups include validated packs; diagnostic JSON exports do not.</p><label for="content-pack-file">Content ZIP · up to 6 MB expanded</label><input id="content-pack-file" type="file" accept=".zip,application/zip"><button data-pack-action="validate">Validate selected ZIP</button><button data-pack-action="bundled">Validate included full character pack</button><button data-pack-action="list">Load saved reports</button>${active?'<button data-pack-action="deactivate">Use built-in ingredients only</button>':''}<p><a href="/examples/content-pack-fixture.zip" download>Download the small integration fixture</a> · contains shortfalls by design, not the finished content collection.</p>${contentPackReports.map(row=>`<button data-pack-action="report" data-pack-digest="${row.digest}">${escapeHtml(row.packId)} · ${escapeHtml(row.packVersion)} · ${row.digest.slice(0,8)}</button>`).join('')}${r?`<h3>${r.valid?'Structural validation passed':'Corrections required'}</h3><p>${escapeHtml(r.packId)} · ${escapeHtml(r.packVersion)} · ${r.recordCount} records</p>${r.errors.length?`<ul role="alert">${r.errors.map(e=>`<li>${escapeHtml(e)}</li>`).join('')}</ul>`:''}<details open><summary>Shortfalls, warnings & limitations · ${r.warnings.length}</summary><ul>${r.warnings.map(e=>`<li>${escapeHtml(e)}</li>`).join('')}</ul></details>${r.valid?`<button data-pack-action="preview" data-pack-digest="${r.digest}">Browse actual content</button><label><input id="content-pack-reviewed" type="checkbox"> I reviewed the content and understand its reported limitations.</label><button data-pack-action="activate" data-pack-digest="${r.digest}">Activate for future character proposals</button>`:''}`:''}${p?contentPackBrowser(p):''}</section>`;
}
async function contentPackAction(action,digest) {
 if(busy||pendingRequest)return;
 if(action==='browse-page'){
  packBrowserPage=Math.max(0,packBrowserPage+Number(digest||0));return render();
 }
 if(action==='browse-group'){packBrowserGroup=document.querySelector('#pack-browser-group')?.value||'';packBrowserPage=0;return render();}
 if(action==='report'){contentPackReport=contentPackReports.find(r=>r.digest===digest);contentPackPreview=null;return render();}
 let path,payload;
 if(action==='list')path=campaignUrl('/api/content-packs');
 else if(action==='preview'){path=campaignUrl('/api/content-packs/preview');payload={digest};}
 else if(action==='activate'||action==='deactivate'){
  if(action==='activate'&&document.querySelector('#content-pack-reviewed')?.checked!==true)return toast('Review the actual content and check the statement first.');
  path=campaignUrl('/api/action');payload={requestId:newRequestId(),expectedRevision:state.revision,action:{type:action==='activate'?'activate-content-pack':'deactivate-content-pack',digest,contentReviewed:true}};
 } else if(action==='bundled'){path=campaignUrl('/api/content-packs/validate');payload={bundled:true};}
 else if(action!=='validate')return;
 busy=true;document.body.classList.add('busy');
 try {
  if(action==='validate'){
   const file=document.querySelector('#content-pack-file')?.files?.[0];
   if(!file||file.size>6000000)throw new Error('Choose a ZIP no larger than 6 MB.');
   const bytes=new Uint8Array(await file.arrayBuffer());let binary='';
   for(let start=0;start<bytes.length;start+=16384)binary+=String.fromCharCode(...bytes.subarray(start,start+16384));
   path=campaignUrl('/api/content-packs/validate');payload={archiveBase64:btoa(binary)};
  }
  const response=await fetch(path,payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{cache:'no-store'});
  const result=await response.json();if(!response.ok){if(result.state)state=result.state;throw new Error(result.error||'Content operation failed.');}
  if(action==='list')contentPackReports=result.packs;
  else if(action==='preview'){contentPackPreview=result;packBrowserGroup='';packBrowserPage=0;}
  else if(action==='validate'||action==='bundled'){contentPackReport=result;contentPackPreview=null;if(result.valid)contentPackReports=[result,...contentPackReports.filter(r=>r.digest!==result.digest)];}
  else state=result;
  render();
 }catch(error){toast(error.message);}
 finally{busy=false;document.body.classList.remove('busy');}
}

function contentPackBrowser(pack) {
 const groups={};
 for(const [a,pools] of Object.entries(pack.ancestries))for(const [kind,rows] of Object.entries(pools))groups[a+' / '+kind]=rows;
 for(const [kind,rows] of Object.entries(pack.shared))groups['Shared / '+kind]=rows;
 if(!groups[packBrowserGroup])packBrowserGroup=Object.keys(groups).find(k=>groups[k].length)||Object.keys(groups)[0];
 const rows=groups[packBrowserGroup],pages=Math.max(1,Math.ceil(rows.length/25));packBrowserPage=Math.min(packBrowserPage,pages-1);
 return `<details open><summary>Content browser · ${escapeHtml(pack.manifest.packId)}</summary><p>Proposed ingredients, not established events. Displaying up to 25 records at a time.</p><details><summary>Pack author’s notes</summary><p style="white-space:pre-wrap">${escapeHtml(pack.readme||'')}</p></details><label for="pack-browser-group">Collection</label><select id="pack-browser-group">${Object.entries(groups).map(([key,records])=>`<option value="${escapeHtml(key)}" ${key===packBrowserGroup?'selected':''}>${escapeHtml(key)} · ${records.length}</option>`).join('')}</select><button data-pack-action="browse-group">Open collection</button><p>Page ${packBrowserPage+1} of ${pages}</p><button data-pack-action="browse-page" data-pack-digest="-1" ${disabledAttrs(packBrowserPage, 'Already on the first page.')}>Previous records</button><button data-pack-action="browse-page" data-pack-digest="1" ${disabledAttrs(packBrowserPage+1<pages, 'Already on the last page.')}>Next records</button>${rows.slice(packBrowserPage*25,(packBrowserPage+1)*25).map(o=>`<details><summary>${escapeHtml(o.name||o.title||o.label||o.id)}</summary>${recordFields(o)}</details>`).join('')}${rows.length?'':'<p>No records in this collection.</p>'}</details>`;
}

function householdContentPage() {
 const v=state.householdContentView;
 if(!v.residents[householdContentOwner])householdContentOwner=Object.keys(v.residents)[0];
 const who=householdContentOwner,owner=v.residents[who],catalogue=householdContentChoices?.residents[who];
 if(!owner)return '<section class="panel"><p>Agree household membership with a resident first.</p></section>';
 const scenes=Object.entries(v.scenes).filter(([,r])=>r.participants.includes(who)).reverse().sort((a,b)=>Number(a[1].status==='remembered')-Number(b[1].status==='remembered'));
 const scenePages=Math.max(1,Math.ceil(scenes.length/25));householdScenePage=Math.min(householdScenePage,scenePages-1);
 const seeds=catalogue?.scenes||[],patterns=catalogue?.patterns||[];
 if(!seeds.some(r=>r.id===householdSeedId))householdSeedId=seeds[0]?.id||'';
 if(!patterns.some(r=>r.id===householdPatternId))householdPatternId=patterns[0]?.id||'';
 const seed=seeds.find(r=>r.id===householdSeedId),pattern=patterns.find(r=>r.id===householdPatternId);
 const evidence=(rows,prefix,verified=[])=>rows.map((line,i)=>`<label for="${prefix}-${i}">${escapeHtml(line)}</label><input id="${prefix}-${i}" maxlength="300" value="${escapeHtml(verified[i]||'')}" ${verified[i]?'readonly':''} placeholder="Basis in established play or reviewed personal agreement">${verified[i]?'<small>Verified by the game’s rules; personal agreement is still separate.</small>':''}`).join('');
 const button=(action,label,extra='')=>`<button data-household-content="${action}" ${extra}>${label}</button>`;
 return `${heading('COMPANY, CLOTHES & PROGRESS','Household life','Choose an available activity or reread a scene you have shared.')}<section class="panel"><label for="household-content-owner">Resident</label><select id="household-content-owner">${Object.entries(v.residents).map(([id,p])=>`<option value="${id}" ${id===who?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select>${button('owner','Choose resident')}${button('load','Load active pack choices')}<p>${escapeHtml(owner.name)} · ${owner.present?'Home together':'Return home together to propose or join scenes and change styles'}. Saved invitations and clothing survive departures and pack changes.</p><button data-view="settings">Manage content pack →</button><button data-view="stories">Personal projects →</button></section>
 ${catalogue?`<section class="panel"><h2>Propose an invitation</h2><label for="household-scene-seed">Interaction seed</label><select id="household-scene-seed">${seeds.map(r=>`<option value="${r.id}" ${r.id===householdSeedId?'selected':''}>${escapeHtml(r.label)} · ${r.participants}</option>`).join('')}</select>${button('seed','Read selected seed')}${seed?`<p>${escapeHtml(seed.description)}</p><blockquote>${escapeHtml(seed.openingInvitation)}</blockquote><p>Participants: ${seed.participants==='npc-player'?'this resident and you':seed.participants==='two-npcs'?'two residents, with you present':'two or three residents, with you present'}. Select additional residents as appropriate.</p><label for="household-partner">Second resident</label><select id="household-partner"><option value="">None</option>${Object.entries(v.residents).filter(([id])=>id!==who).map(([id,r])=>`<option value="${id}">${escapeHtml(r.name)}</option>`).join('')}</select><label for="household-third">Third resident · group scenes only</label><select id="household-third"><option value="">None</option>${Object.entries(v.residents).filter(([id])=>id!==who).map(([id,r])=>`<option value="${id}">${escapeHtml(r.name)}</option>`).join('')}</select><details open><summary>Narrative prerequisites</summary>${evidence(seed.requirements,'scene-evidence',seed.verifiedRequirements)}<label><input id="scene-prerequisites-reviewed" type="checkbox"> These notes reflect established play and willing participation; they grant no resources or unlocks.</label></details>${button('propose','Compose reviewable invitation')}`:'<p>No compatible seeds.</p>'}</section>
 <section class="panel"><h2>Her next story’s shape</h2><p>A pattern supplies optional structure to future story drafts; the selected work package still determines all costs and rewards.</p><select id="household-pattern" aria-label="Story pattern">${patterns.map(r=>`<option value="${r.id}" ${r.id===householdPatternId?'selected':''}>${escapeHtml(r.label)}</option>`).join('')}</select>${button('pattern','Read selected pattern')}${pattern?`<p>${escapeHtml(pattern.description)}</p><p>${escapeHtml(pattern.meaningfulChoice)}</p>${evidence(pattern.requiredEstablishedFacts,'pattern-evidence')}<label><input id="pattern-prerequisites-reviewed" type="checkbox"> I reviewed the stated narrative prerequisites.</label>${button('choose-pattern','Use for future story drafts')}`:''}<p>Selected: ${escapeHtml(owner.storyPattern?.pattern.label||'No imported pattern')}.</p>${button('clear-pattern','Clear future pattern')}</section>
 <section class="panel"><h2>Compose a personal style</h2><p>Cosmetic wardrobe choices use no time, funds or equipment bonuses. Review her willingness, opaque coverage and individual anatomy. Portraits remain separately reviewed illustrations.</p><label for="household-ensemble">Starting ensemble</label><select id="household-ensemble"><option value="">Custom components below</option>${catalogue.ensembles.map(r=>`<option value="${r.id}">${escapeHtml(r.label)}</option>`).join('')}</select>${button('ensemble','Inspect ensemble')}<div id="household-ensemble-preview"></div><details><summary>Garments · select for a custom look</summary>${catalogue.garments.map(r=>`<details><summary><label><input type="checkbox" id="household-garment-${r.id}" value="${r.id}"> ${escapeHtml(r.label)} · ${r.slot}</label></summary>${recordFields(r)}</details>`).join('')}</details><label for="household-style-name">Style name</label><input id="household-style-name" maxlength="60"><label for="household-style-notes">Styling notes</label><textarea id="household-style-notes" maxlength="600"></textarea><label><input id="household-anatomy-reviewed" type="checkbox"> Coverage, layers and openings fit her actual body.</label><label><input id="household-style-agreed" type="checkbox"> This is a look she welcomes.</label>${button('save-style','Save look · wearing it is a separate choice')}</section>`:'<section class="panel"><p>Load the active pack to propose new scenes or styles. Saved choices below remain usable without it.</p></section>'}
 <section class="panel"><h2>Saved styles</h2><p>Current: ${escapeHtml(owner.styles[owner.currentStyleId]?.name||'Established look')}.</p>${button('restore-look','Restore established look')}<label><input id="household-wear-agreed" type="checkbox"> She welcomes this change of style.</label>${Object.entries(owner.styles).map(([id,r])=>`<details><summary>${escapeHtml(r.name)}${owner.currentStyleId===id?' · wearing now':''}</summary><p>${escapeHtml(r.stylingNotes)}</p>${r.components.map(c=>`<p>${escapeHtml(c.label)} · ${escapeHtml(c.coverage)}</p>`).join('')}${button('wear-style','Wear this look',`data-style-id="${id}"`)}${button('remove-style','Forget saved style',`data-style-id="${id}"`)}</details>`).join('')}<p>Current clothing is supplied to her dialogue context. Existing portraits are not automatically repainted.</p></section>
 <h2>Invitations & remembered conversations</h2><p>Page ${householdScenePage+1} of ${scenePages} · active invitations first, memories retained.</p>${button('scene-page','Previous conversations',`data-choice-index="-1" ${disabledAttrs(householdScenePage, 'Already on the first page.')}`)}${button('scene-page','Next conversations',`data-choice-index="1" ${disabledAttrs(householdScenePage+1<scenePages, 'Already on the last page.')}`)}${scenes.slice(householdScenePage*25,(householdScenePage+1)*25).map(([id,r])=>`<section class="panel"><p class="eyebrow">${r.status}</p><h3>${escapeHtml(r.title)}</h3><p>${r.participants.map(p=>escapeHtml(state.people[p].name)).join(' & ')}</p><blockquote>${escapeHtml(r.invitation)}</blockquote>${r.status==='draft'?`<details open><summary>Review and refine the scene</summary><label>Title<input id="scene-title-${id}" maxlength="80" value="${escapeHtml(r.title)}"></label><label>Invitation<textarea id="scene-invitation-${id}" maxlength="600">${escapeHtml(r.invitation)}</textarea></label><label>Opening<textarea id="scene-opening-${id}" maxlength="600">${escapeHtml(r.opening)}</textarea></label>${r.choices.map((c,i)=>`<label>${escapeHtml(c.label)}<textarea id="scene-reply-${id}-${i}" maxlength="600">${escapeHtml(c.reply)}</textarea></label>`).join('')}${sceneDraftPanel(id)}${button('revise','Save scene revisions',`data-scene-id="${id}"`)}<p>Save revisions before approving. Approval applies to the saved text.</p><label><input id="scene-reviewed-${id}" type="checkbox"> I reviewed the saved scene and every response: no invented completed work, forced intimacy or private disclosures.</label>${button('approve','Offer reviewed invitation',`data-scene-id="${id}"`)}</details>`:r.status==='waiting'?`<p>${escapeHtml(r.opening)}</p>${r.choices.map((c,i)=>button('join',escapeHtml(c.label),`data-scene-id="${id}" data-choice-index="${i}" ${disabledAttrs(r.canJoin, 'All participants must be available at home before joining this scene.')}`)).join('')}${button('defer','Another time · no expiry or penalty',`data-scene-id="${id}"`)}`:r.status==='withdrawn'?`<p>${escapeHtml(r.lastResponse||'This invitation was withdrawn.')}</p>`:r.status==='deferred'?`<p>${escapeHtml(r.lastResponse||'This invitation is set aside. Restore it when you want to continue.')}</p>`+button('restore','Restore invitation',`data-scene-id="${id}"`):r.completedText.map(t=>`<p>${escapeHtml(t)}</p>`).join('')+`<p><strong>Possible follow-through · not completed:</strong> ${escapeHtml(r.choices[r.choiceIndex].possibleNextStep||'')}</p>`}<details><summary>Source and prerequisite record</summary><p>${escapeHtml(r.source.packId)} · ${escapeHtml(r.source.packVersion)}</p>${(r.prerequisiteEvidence||[]).map(e=>`<p>${escapeHtml(e.requirement)} — ${escapeHtml(e.reviewedBasis)}</p>`).join('')}</details></section>`).join('')}
 <section class="panel"><h2>Shared history</h2>${v.sharedHistory.filter(r=>r.participants.includes(who)).map(r=>`<p>${r.participants.map(p=>escapeHtml(state.people[p].name)).join(' & ')}: ${escapeHtml(r.description)}</p>`).join('')||'<p>No shared group conversations recorded yet.</p>'}<p>History records what was shared, without assigning affection scores, jealousy or compulsory romance.</p></section>`;
}
async function householdContentAction(action,data={}) {
 if(busy||pendingRequest)return;
 const value=id=>document.querySelector('#'+id)?.value||'',checked=id=>document.querySelector('#'+id)?.checked===true;
 if(action==='scene-page'){householdScenePage=Math.max(0,householdScenePage+Number(data.choiceIndex));return render();}
 if(action==='owner'){householdContentOwner=value('household-content-owner');householdScenePage=0;return render();}
 if(action==='seed'){householdSeedId=value('household-scene-seed');return render();}
 if(action==='pattern'){householdPatternId=value('household-pattern');return render();}
 if(action==='load'){
  busy=true;try{const r=await fetch(campaignUrl('/api/household-content'),{cache:'no-store'});const j=await r.json();if(!r.ok)throw new Error(j.error);householdContentChoices=j;render();}catch(e){toast(e.message);}finally{busy=false;}return;
 }
 const c=householdContentChoices?.residents[householdContentOwner];
 if(action==='ensemble'){
  const selected=c?.ensembles.find(r=>r.id===value('household-ensemble'));
  if(!selected)return toast('Choose an ensemble to inspect, or select individual garments.');
  document.querySelector('#household-style-name').value=selected.label;
  document.querySelector('#household-style-notes').value=selected.stylingNotes;
  document.querySelector('#household-ensemble-preview').innerHTML=recordFields(selected)+selected.componentIds.map(id=>c.garments.find(g=>g.id===id)).filter(Boolean).map(recordFields).join('');
  return;
 }
 if(action==='approve'){
  const saved=state.householdContentView.scenes[data.sceneId];
  const controls=[['scene-title-'+data.sceneId,saved.title],['scene-invitation-'+data.sceneId,saved.invitation],['scene-opening-'+data.sceneId,saved.opening],...saved.choices.map((c,i)=>['scene-reply-'+data.sceneId+'-'+i,c.reply])];
  if(controls.some(([id,text])=>document.querySelector('#'+id)?.value!==undefined&&value(id)!==text))return toast('Save your scene revisions before approving the invitation.');
 }
 const base={ownerId:householdContentOwner,packDigest:householdContentChoices?.pack?.digest};let change;
 const evidence=(rows,prefix)=>rows.map((_,i)=>value(prefix+'-'+i));
 if(action==='propose'){
  const seed=c?.scenes.find(r=>r.id===householdSeedId);if(!seed)return;
  change={...base,type:'propose-content-scene',seedId:seed.id,participants:[householdContentOwner,value('household-partner'),value('household-third')].filter(Boolean),prerequisitesReviewed:checked('scene-prerequisites-reviewed'),requirementEvidence:evidence(seed.requirements,'scene-evidence',seed.verifiedRequirements)};
 }else if(action==='choose-pattern'){
  const p=c?.patterns.find(r=>r.id===householdPatternId);if(!p)return;
  change={...base,type:'choose-story-pattern',patternId:p.id,prerequisitesReviewed:checked('pattern-prerequisites-reviewed'),requirementEvidence:evidence(p.requiredEstablishedFacts,'pattern-evidence')};
 }else if(action==='save-style')change={...base,type:'save-content-style',ensembleId:value('household-ensemble'),componentIds:(c?.garments||[]).filter(r=>checked('household-garment-'+r.id)).map(r=>r.id),name:value('household-style-name'),stylingNotes:value('household-style-notes'),anatomyReviewed:checked('household-anatomy-reviewed'),residentAgreed:checked('household-style-agreed')};
 else if(action==='revise'){
  const r=state.householdContentView.scenes[data.sceneId];
  change={type:'revise-content-scene',sceneId:data.sceneId,title:value('scene-title-'+data.sceneId),invitation:value('scene-invitation-'+data.sceneId),opening:value('scene-opening-'+data.sceneId),replies:r.choices.map((_,i)=>value('scene-reply-'+data.sceneId+'-'+i))};
 }else {
  const types={approve:'approve-content-scene',join:'join-content-scene',defer:'defer-content-scene',restore:'restore-content-scene','wear-style':'wear-content-style','remove-style':'remove-content-style','restore-look':'restore-content-look','clear-pattern':'clear-story-pattern'};
  if(!types[action])return;
  change={...base,type:types[action],sceneId:data.sceneId,styleId:data.styleId,choiceIndex:Number(data.choiceIndex),contentReviewed:checked('scene-reviewed-'+data.sceneId),residentAgreed:checked('household-wear-agreed')};
 }
 await commit(change,'Household choice saved.');
}


let equipmentOwner='founder';
function equipmentPage(){
 const v=state.equipmentView;if(!v.people[equipmentOwner])equipmentOwner='founder';
 const who=equipmentOwner,person=v.people[who],home=person.atHome&&state.founderAtCastle;
 const btn=(kind,label,id='',enabled=home)=>`<button data-tool-action="${kind}" data-item-id="${id}" ${enabled?'':'disabled'}>${label}</button>`;
 return `${heading('OWNED, NAMED & PUT TO USE','Personal working tools','One prepared working tool per person. Bonuses apply only during the listed assigned work.')}<section class="panel"><label for="equipment-owner">Owner</label><select id="equipment-owner">${Object.entries(v.people).map(([id,p])=>`<option value="${id}" ${id===who?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select>${btn('owner','Choose owner','',true)}<p>${home?'At home: ownership and preparation can be agreed.':'Return home together to change equipment.'}</p><button data-focus-character="${escapeHtml(who)}">Signature focus inscriptions & upgrades →</button><button data-view="workshop">Craft a working tool →</button><button data-view="research">Research its principle →</button></section>
 ${fieldcraftJourney()}${toolUpgradePanel(who)}${toolInvitations(who)}<section class="panel"><h2>Claim a crafted tool</h2><p>Claiming takes one finished copy from shared stores. It adds no time or cost. A tool must then be prepared.</p>${Object.entries(v.catalogue).map(([id,d])=>`<h3>${escapeHtml(d.name)}</h3><p>${escapeHtml(d.benefit)}</p><p>Required crafting knowledge: ${escapeHtml(state.principleNames[d.principle])}. Finished copies: ${state.craftedArtifacts[id]||0}.</p>${btn('claim',`Assign one to ${escapeHtml(person.name)}`,id,home&&(state.craftedArtifacts[id]||0)>0)}`).join('')}</section>
 <section class="panel"><h2>${escapeHtml(person.name)}’s equipment</h2><p>Prepared: ${escapeHtml(v.items[v.prepared[who]]?.name||'None')}. Preparing another tool stows the previous one; bonuses do not stack with other working tools. Signature-focus bonuses are separate.</p>${btn('stow','Stow prepared tool','',home&&!!v.prepared[who])}${Object.entries(v.items).filter(([,i])=>i.ownerId===who).map(([id,i])=>`<details open><summary>${escapeHtml(i.name)}${v.prepared[who]===id?' · prepared':''}</summary><p>${escapeHtml(v.catalogue[i.kind].benefit)}</p><p>${i.inscription?escapeHtml(i.inscription.name)+' · +2 matching work, replacing the original +1.':'No inscription · +1 matching work.'}</p>${!i.inscription?toolUpgradeForm(id,who):''}${btn('prepare','Prepare',id)}<label for="tool-name-${id}">Personal name</label><input id="tool-name-${id}" maxlength="60" value="${escapeHtml(i.name)}">${btn('rename','Save name',id)}<p>Ownership: ${i.ownershipHistory.map(p=>escapeHtml(state.people[p]?.name||p)).join(' → ')}</p><label for="tool-recipient-${id}">New owner</label><select id="tool-recipient-${id}">${Object.entries(v.people).filter(([p])=>p!==who).map(([p,r])=>`<option value="${p}">${escapeHtml(r.name)}${r.atHome?'':' · away'}</option>`).join('')}</select><label><input type="checkbox" id="tool-agreed-${id}"> Both people agree to the transfer.</label>${btn('transfer','Transfer ownership · stows this tool',id)}</details>`).join('')||'<p>No individually owned tools yet.</p>'}</section>`;
}
async function equipmentAction(kind,data){
 if(busy||pendingRequest)return;
 const val=id=>document.querySelector('#'+id)?.value;
 if(kind==='owner'){equipmentOwner=val('equipment-owner');return render();}
 const types={upgrade:'upgrade-working-tool',resume:'resume-tool-upgrade',cancel:'cancel-tool-upgrade',work:'join-tool-moment',playful:'join-tool-moment',defer:'defer-tool-moment',restore:'restore-tool-moment',claim:'claim-working-tool',prepare:'prepare-working-tool',stow:'stow-working-tool',rename:'rename-working-tool',transfer:'transfer-working-tool'};
 if(!types[kind])return;
 await commit({type:types[kind],ownerId:data.ownerId||equipmentOwner,choice:kind,materials:[val('tool-vessel-'+data.itemId),val('tool-binding-'+data.itemId)],toolId:data.itemId,itemId:data.itemId,name:val('tool-name-'+data.itemId),recipientId:val('tool-recipient-'+data.itemId),ownersAgreed:document.querySelector('#tool-agreed-'+data.itemId)?.checked===true},'Equipment saved.');
}
let sceneProposals={},sceneRequests={};
function sceneDraftPanel(id){
 const d=sceneProposals[id],request=sceneRequests[id];
 const btn=(action,label,enabled=true)=>`<button data-scene-draft="${action}" data-scene-id="${id}" ${enabled?'':'disabled'}>${label}</button>`;
 return `<details><summary>Optional model-written scene</summary><p>Uses your configured text provider. Review every response before applying; applying prose leaves this invitation unapproved. Manual editing above remains available.</p><label for="scene-brief-${id}">Direction for the draft</label><textarea id="scene-brief-${id}" maxlength="600" placeholder="A little teasing, grounded in her interests…"></textarea>${btn('new','Request scene draft',!request)}${btn('recover','Recover saved draft')}${request?btn('retry','Check / retry same request'):''}${d?`<p>${escapeHtml(d.status)} · ${escapeHtml(d.model||'')}</p>${d.error?`<p role="alert">${escapeHtml(d.error)}</p>`:''}${d.proposal?`<h4>${escapeHtml(d.proposal.title)}</h4><p>${escapeHtml(d.proposal.invitation)}</p><p>${escapeHtml(d.proposal.opening)}</p>${d.proposal.replies.map((t,i)=>`<p><strong>${escapeHtml(state.householdContentView.scenes[id].choices[i].label)}</strong><br>${escapeHtml(t)}</p>`).join('')}`:''}${d.status==='ready'?`<label><input type="checkbox" id="scene-model-reviewed-${id}"> I reviewed the entire draft and every response.</label>${btn('apply','Apply prose to editable invitation',d.baseRevision===state.revision)}${d.baseRevision!==state.revision?'<p>The campaign changed. Start a new draft or manually copy suitable wording into the editor.</p>':''}`:''}<p>Reported tokens: ${d.usage?.total_tokens??'not supplied'}. Processing requests may already incur provider usage; retries use the same saved request.</p>${btn('dismiss','Put preview aside')}`:''}</details>`;
}
async function sceneDraftAction(action,id){
 if(busy||pendingRequest)return;
 if(['new','recover','retry','dismiss'].includes(action)){
  const saved=state.householdContentView.scenes[id];
  const fields=[['scene-title-'+id,saved.title],['scene-invitation-'+id,saved.invitation],['scene-opening-'+id,saved.opening],...saved.choices.map((c,i)=>['scene-reply-'+id+'-'+i,c.reply])];
  if(fields.some(([key,text])=>document.querySelector('#'+key)?.value!==undefined&&document.querySelector('#'+key).value!==text))return toast('Save your scene revisions before requesting or recovering a model draft.');
 }
 if(action==='dismiss'){delete sceneProposals[id];delete sceneRequests[id];return render();}
 let path,payload;
 if(action==='recover')path=campaignUrl('/api/dialogue/drafts')+'&purpose=scene-proposal&scene='+encodeURIComponent(id);
 else if(action==='apply'){
  if(!sceneProposals[id])return;
  if(!document.querySelector('#scene-model-reviewed-'+id)?.checked)return toast('Review the entire model-written scene first.');
  path=campaignUrl('/api/dialogue/accept');payload={draftId:sceneProposals[id].id,contentReviewed:true};
 }else{
  if(action==='new'&&!sceneRequests[id])sceneRequests[id]={requestId:newRequestId(),purpose:'scene-proposal',sceneId:id,expectedRevision:state.revision,text:document.querySelector('#scene-brief-'+id)?.value?.trim()||'A warm, lightly teasing invitation in her own voice.'};
  if(!sceneRequests[id])return;
  path=campaignUrl('/api/dialogue/draft');payload=sceneRequests[id];
 }
 busy=true;document.body.classList.add('busy');
 try{
  const r=await fetch(path,payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{cache:'no-store'});
  const j=await r.json();if(!r.ok)throw new Error(j.error||'Scene drafting failed.');
  if(action==='apply'){state=j;delete sceneProposals[id];delete sceneRequests[id];}
  else if(action==='recover'){
   const d=j.drafts.find(d=>d.sceneId===id&&['processing','ready','failed'].includes(d.status));
   if(d){sceneProposals[id]=d;sceneRequests[id]={requestId:d.id,purpose:'scene-proposal',sceneId:id,expectedRevision:d.baseRevision,text:d.userText};}else toast('No pending draft for this invitation.');
  }else sceneProposals[id]=j;
  render();
 }catch(e){toast(e.message);}finally{busy=false;document.body.classList.remove('busy');}
}
let expansionReports=[],expansionReport=null,expansionPreview=null,expansionPreviewDigest='',expansionBundleReport=null,expansionSelectedRecord='';
function expansionPanel(){
 return `<section class="panel"><h2>Public expansion content</h2><button data-view="publicWorkshop">Open the playable public workshop →</button><p>Review all sixteen public expansion packs here. The public workshop runs the shipped, reviewed rule adapters. Uploads remain source proposals: staging a revised pack never changes the executable rules.</p><p><a href="/examples/expansion-design-fixture.zip" download>Download a small example ZIP</a> · two records, with honest quantity shortfalls.</p><button data-expansion-action="bundled">Validate & stage included public bundle</button>${expansionBundleReport?`<p role="status">${expansionBundleReport.packs.length} packs · ${expansionBundleReport.contentCount} content records · ${expansionBundleReport.mechanicsCount} source mechanics proposals. Use the workshop for the shipped implementations. ${escapeHtml(expansionBundleReport.message)}</p>`:''}<label for="expansion-file">Single expansion ZIP</label><input id="expansion-file" type="file" accept=".zip"><button data-expansion-action="validate">Validate & stage design</button><button data-expansion-action="load">Saved design reviews</button>${expansionReport?`<p>${expansionReport.valid?'Structure accepted':'Needs correction'} · ${expansionReport.recordCount} records</p>${[...expansionReport.errors,...expansionReport.warnings].map(t=>`<p>${escapeHtml(t)}</p>`).join('')}`:''}${expansionReports.map(r=>`<p>${escapeHtml(r.packId)} · ${escapeHtml(r.packVersion)} · ${r.contentCount??r.recordCount} content · ${r.mechanicsCount??0} proposed mechanics <button data-expansion-action="preview" data-digest="${r.digest}">Inspect proposal</button></p>`).join('')}${expansionPreview?`<details open><summary>${escapeHtml(expansionPreview.manifest.packId)} · proposed design only</summary><p>Choose a record to inspect. These are original source proposals. The public workshop shows the shipped executable costs and controls; uploaded prose never grants an effect.</p><select id="expansion-record" aria-label="Design record">${Object.entries(expansionPreview.entries).map(([id,r])=>`<option value="${escapeHtml(id)}" ${id===expansionSelectedRecord?'selected':''}>${escapeHtml(expansionPreview.types[id])} · ${escapeHtml(r.name)}</option>`).join('')}</select><button data-expansion-action="record">Read record</button><div id="expansion-record-preview" aria-live="polite"></div><details><summary>Author’s notes</summary><p style="white-space:pre-wrap">${escapeHtml(expansionPreview.sourceFiles['README.md'])}</p></details></details>`:''}</section>`;
}
async function expansionAction(action,digest){
 if(busy||pendingRequest)return;
 if(action==='record'){const id=document.querySelector('#expansion-record')?.value;expansionSelectedRecord=id;const r=expansionPreview.entries[id];document.querySelector('#expansion-record-preview').innerHTML=recordFields(r||{})+(r&&expansionPreview.types[id]==='scene-template'?expansionSceneForm(r):'');return;}
 if(action==='compose')return composeExpansionScene();
 let path=campaignUrl('/api/expansion-packs'),payload;
 busy=true;
 try{
  if(action==='bundled'){path=campaignUrl('/api/expansion-packs/bundled');payload={};}
  else if(action==='validate'){
   const file=document.querySelector('#expansion-file')?.files?.[0];if(!file)throw new Error('Choose an expansion ZIP.');
   if(file.size>6*1024*1024)throw new Error('Keep the ZIP below 6 MiB.');
   const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));
   payload={archiveBase64:btoa(binary)};path=campaignUrl('/api/expansion-packs/validate');
  }else if(action==='preview'){path=campaignUrl('/api/expansion-packs/preview');payload={digest};}
  const r=await fetch(path,payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{cache:'no-store'});const j=await r.json();if(!r.ok)throw new Error(j.error||'Design review failed.');
  if(action==='bundled'){expansionBundleReport=j;expansionReports=j.packs;}else if(action==='validate')expansionReport=j;else if(action==='preview'){expansionPreview=j;expansionPreviewDigest=digest;expansionSelectedRecord='';}else expansionReports=j.packs;
  render();
 }catch(e){toast(e.message);}finally{busy=false;}
}


