 if(r.recordType==='ritual-concept')html+=r.roles.map((name,i)=>publicSelect('public-role-'+i,name,Object.entries(state.publicWorkshopView.actors).map(([k,p])=>[k,p.name]))).join('')+'<p>Each role takes its own stated phases. One person taking two roles works them sequentially. All participants can withdraw.</p>'+button('start-ritual','Agree roles & begin ritual');
 if(r.recordType==='augmentation-concept')html+='<p>One assigned phase; no fee. Describe the original appearance above. End the trial immediately and freely, including during work.</p>'+button('augment','Begin requested reversible trial');
