 if(r.recordType==='room-purpose')html+='<p>This legacy room-purpose concept is now a zone within a multi-use headquarters room. Existing saved purposes are retained.</p><button data-view="headquarters">Open consolidated room options →</button>';
 if(r.recordType==='furnishing-concept'&&!rule)html+=button('decorate-room','Choose this free decoration');
 if(r.recordType==='adjacency-synergy'&&rule)html+=publicSelect('public-second-room','Second connected room',state.availableRoomIds.map(k=>[k,state.rooms[k].name]))+publicSelect('public-receipt','Completed supporting evidence',state.publicWorkshopView.receipts.filter(x=>x.status==='complete').map(x=>[x.id,x.name]))+button('select-support','Select this optional support')+button('clear-support','Put support aside');
 if(r.recordType==='starting-package-concept')html+='<p>Choose this package only when creating a new solo campaign in Settings & artwork. It grants one limited principle, one basic practice and one uninscribed focus, with no earned ranks. Existing people are never rewritten.</p>';
