 if(['book-or-document','food-or-drink','garden-specimen','curiosity','gift-or-keepsake'].includes(r.recordType))html+='<p>Provisioning includes modest supplies in the disclosed price: books 6 crowns / 2 phases; meals 4 / 1; potted specimens 8 / 2; curiosities 6 / 2; keepsakes 4 / 2. No knowledge, magical properties or output bonuses are granted.</p>'+button('make-household-object','Acquire supplies & assign preparation');
 if(r.recordType==='book-or-document')html+=button('read-object','Read owned copy · 1 phase');
 if(r.recordType==='food-or-drink')html+=button('share-meal','Choose the actual prepared meal');
 if(r.recordType==='letter-template')html+=button('compose-letter','Compose reviewed fictional letter to selected recipient');
