 const cards=available.map(m=>`<details class="panel solo-moment" ${selectedSoloMomentId===m.id?'open':''}><summary>${escapeHtml(m.title)}</summary><img class="moment-art" src="${assetUrl(m.art)}" alt="${m.art==='library'?'The castle library':'The restored conservatory'}" loading="lazy"><p>${escapeHtml(m.opening)}</p><p class="muted">Choose a reflection. No time or resources are spent.</p><div class="room-actions">${m.choices.map(c=>`<button data-solo-moment="${m.id}" data-moment-choice="${c.id}" ${disabledAttrs(m.available,'Return to the castle to enjoy this moment.')}>${escapeHtml(c.label)}</button>`).join('')}</div></details>`).join('');
 return `<section class="panel"><h2>Small moments at home</h2><p>Optional reflections on what you have built. They never expire.</p>${cards||'<p>New moments appear as you make, restore and explore.</p>'}${remembered.length?`<details ${remembered.some(m=>m.id===selectedSoloMomentId)?'open':''}><summary>Shared experiences (${remembered.length})</summary>${remembered.map(m=>`<h3>${escapeHtml(m.title)}</h3><p>${escapeHtml(m.memory.text)}</p><small>Day ${m.memory.dayNumber} · ${escapeHtml(m.memory.phase)}</small>`).join('')}</details>`:''}</section>`;
