// Shared presentation layer: no changes to rules, saves, or action routing.
function disabledAttrs(available, reasons) {
  if(available)return '';
  const text=(Array.isArray(reasons)?reasons.filter(Boolean).join(' '):reasons)||'Review the requirements below.';
  return `disabled data-disabled-reason="${escapeHtml(text)}" title="${escapeHtml(text)}"`;
}
function portraitPeople() {
  if(uiPortraitCache)return uiPortraitCache;
  const people={};
  for(const [id,d] of Object.entries(state.localEncounterView?.encounters||{}))people[id]=d;
  for(const [id,d] of Object.entries(state.summoningView?.candidates||{}))people[id]=d.profile;
  Object.assign(people,state.people||{});
  uiPortraitCache=people;return people;
}
function portraitImage(who, size='inline') {
  const person=portraitPeople()[who]||{name:who};
  const styled=residentPortraitId(who);
  const key=state.assetOverrides?.[styled]||state.originalAssets?.[styled]?styled:who;
  const url=state.assetOverrides?.[key]?campaignUrl(state.assetOverrides[key]):state.originalAssets?.[key];
  const pending=!url||url.includes('visitor-placeholder');
  return `<span class="identity-portrait portrait-${size}${pending?' portrait-pending':''}" title="${escapeHtml(person.name)}${pending?' · portrait not yet illustrated':''}" data-person-portrait="${escapeHtml(who)}"><img class="portrait-art${!pending&&!state.assetOverrides?.[key]&&size!=='card'?' portrait-crop':''}" src="${escapeHtml(pending?'/assets/ui/castle-emblem.webp':url)}" alt="" width="${size==='inline'?28:size==='strip'?48:144}" height="${size==='inline'?28:size==='strip'?48:180}" loading="lazy"></span>`;
}
function householdStrip() {
  const people=Object.entries(state.characterCatalog||{});
  if(!people.length)return '';
  return `<section class="household-strip" aria-label="Household assignments">${people.map(([who,p])=>{
    const sheet=state.characterSheets[who],home=sheet?.atCastle;
    return `<button class="household-chip" data-person-context="${escapeHtml(who)}">${portraitImage(who,'strip')}<span data-identity-label="yes"><strong>${escapeHtml(p.name)}</strong><small>${home?escapeHtml(assignmentLabel(sheet.assignment||'rest')):'Away from the castle'}</small></span></button>`;
  }).join('')}</section>`;
}
function plainMarkup(html) {
  return html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
}
function explainDisabled(html) {
  let serial=0;
  // Unavailable buttons remain focusable: their only action is an explanation.
  // Native form fields keep their disabled state with a separate disclosure.
  return html.replace(/<(button|select|input|textarea)\b((?:"[^"]*"|'[^']*'|[^'">])*)>([\s\S]*?)<\/\1>|<input\b((?:"[^"]*"|'[^']*'|[^'">])*)>/gi,(full,tag,attrs,body,inputAttrs,offset)=>{
    attrs=attrs||inputAttrs||'';tag=tag||'input';
    if(!/(?:^|\s)disabled(?:\s|=|$)/.test(attrs))return full;
    const exact=attrs.match(/(?:data-disabled-reason|title)="([^"]+)"/);
    // Legacy panels already explain requirements in prose. Keep those facts
    // accessible beside their controls while they migrate to explicit reasons.
    const before=html.slice(0,offset),starts=[...before.matchAll(/<(?:section|article|form|li)\b/g)];
    const start=starts.length?starts.at(-1).index:Math.max(0,offset-900);
    const after=html.slice(offset+full.length),end=after.search(/<\/(?:section|article|form|li)>/);
    const context=plainMarkup(html.slice(start,offset)+after.slice(0,end<0?400:Math.min(end,1600))).slice(0,1800);
    const reason=exact?exact[1]:`Current requirements and status: ${context.replaceAll('"','&quot;')||'This control is fixed for the current selection.'}`;
    if(tag.toLowerCase()==='button') {
      const cleaned=attrs.replace(/(?:^|\s)disabled(?:="[^"]*"|='[^']*'|(?=\s|$))/,'').replace(/\s(?:data-disabled-reason|title)="[^"]*"/g,'');
      return `<button${cleaned} aria-disabled="true" data-disabled-reason="${reason}" title="${reason}">${body}</button>`;
    }
    const id=`unavailable-${++serial}`;
    const control=full.replace(new RegExp('^<'+tag+'\\b'),`<${tag} aria-describedby="${id}"`);
    return `<span class="unavailable-control">${control}<details class="unavailable-help"><summary aria-label="Why unavailable: ${plainMarkup(body||'this field')}">Why unavailable?</summary><span class="unavailable-reason" id="${id}">${reason}</span></details></span>`;
  });
}
function illustrateNames(html) {
  const entries=Object.entries(portraitPeople()).filter(([,p])=>p.name?.length>=3);
  const byName=new Map();for(const [id,p] of entries)if(!byName.has(escapeHtml(p.name).toLowerCase()))byName.set(escapeHtml(p.name).toLowerCase(),id);
  const names=[...byName.keys()].sort((a,b)=>b.length-a.length);
  if(!names.length)return html;
  const pattern=new RegExp('(?<![\\p{L}\\p{N}_])('+names.map(n=>n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\p{L}\\p{N}_])','giu');
  const stack=[];
  return html.split(/(<(?:"[^"]*"|'[^']*'|[^'">])*?>)/g).map(token=>{
    if(token.startsWith('<')){
      const closing=token.match(/^<\/([\w-]+)/),opening=token.match(/^<([\w-]+)/);
      if(closing){const i=stack.map(x=>x.tag).lastIndexOf(closing[1].toLowerCase());if(i>=0)stack.splice(i);}
      else if(opening){
        const portrait=token.match(/data-person-portrait="([^"]+)"/);
        if(portrait){
          // An explicit portrait already represents this person in the nearest row.
          const block=[...stack].reverse().find(x=>['p','li','button','h1','h2','h3','h4','summary','td'].includes(x.tag))||stack.at(-1);
          block?.seen.add(portrait[1]);
        }
        if(!/^(?:img|input|br|hr|meta|link|source|wbr)$/i.test(opening[1]))stack.push({seen:new Set(),tag:opening[1].toLowerCase(),skip:/data-identity-label=|data-person-portrait=/.test(token)});
      }
      return token;
    }
    if(stack.some(x=>x.skip||['select','option','textarea','script','style','code','pre'].includes(x.tag)))return token;
    // Match escaped visible names, never HTML attributes or editable values.
    return token.replace(pattern,name=>{const who=byName.get(name.toLowerCase()),block=[...stack].reverse().find(x=>['p','li','button','h1','h2','h3','h4','summary','td'].includes(x.tag))||stack.at(-1);if(block?.seen.has(who))return name;block?.seen.add(who);const interactive=!stack.some(x=>['button','a','label','summary'].includes(x.tag));return `<span class="named-person">${portraitImage(who).replace('<span ',interactive?`<span role="button" tabindex="0" aria-label="About ${escapeHtml(portraitPeople()[who].name)}" data-person-context="${escapeHtml(who)}" `:'<span ')}<span>${name}</span></span>`;});
  }).join('');
}
function explainOptions(html) {
 return html.replace(/<select\b[^>]*>[\s\S]*?<\/select>/g,select=>{
   const options=[...select.matchAll(/<option\b([^>]*)>([\s\S]*?)<\/option>/g)].filter(m=>/(?:^|\s)disabled(?:\s|=|$)/.test(m[1]));
   if(!options.length)return select;
   return select+`<details class="unavailable-help"><summary>Why are some choices unavailable?</summary><ul>${options.map(m=>{const reason=m[1].match(/data-disabled-reason="([^"]+)"/);return `<li>${m[2]}${reason?' — '+reason[1]:''}</li>`;}).join('')}</ul></details>`;
 });
}
function presentUI(html) {return illustrateNames(explainDisabled(explainOptions(illustrateSelects(html))));}

