 ledger:'ledger',workroom:'ledger',magicReference:'spellbook',spells:'spellbook',rituals:'rituals',requests:'letters',commissions:'letters',mystery:'history',publicWorkshop:'materials',equipment:'equipment',workingTools:'equipment',development:'spellbook',customization:'equipment'
