 characterProfile:'common-room',householdChapters:'common-room',householdSagas:'common-room',workArrangements:'command-room',householdContent:'common-room',workshop:'workshop',focus:'enchanting-room',household:'common-room',householdWork:'common-room',wardrobe:'bedchamber',stories:'library',
