 if(target.characterTab)uiCharacterTab=target.characterTab;
 if(target.buildPage&&target.personId)buildUi(target.personId).page=target.buildPage;
 if(Number.isInteger(target.closenessStage)&&target.personId)intimacyStage[target.personId]=target.closenessStage;
 if(target.almanacId)uiAlmanacFocus=target.almanacId;
 if(target.threadId)uiThreadFocus=target.threadId;
 if(target.sceneId){socialFocus=target.sceneId;socialCategory='all';}
 if(target.sagaId){selectedSaga=target.sagaId;sagaTab='stories';}
 if(target.questId)questFocus=target.questId;
 if(target.chapterPerson){chapterPerson=target.chapterPerson;chapterSection=target.chapterSection||'personal';}
 if(target.personId){if(state.armouryView?.workers[target.personId]){gearOwner=target.personId;equipmentOwner=target.personId;gearItem=null;gearQuote=null;}selectedSummoningPerson=target.personId;selectedCharacterId=target.personId;selectedMakerId=state.characterCatalog[target.personId]?target.personId:'founder';storyOwnerId=target.personId;publicOwnerId=target.personId;householdContentOwner=target.personId;}
 if(target.recipeId){selectedRecipeId=target.recipeId;readyRecipesOnly=false;}
 if(target.siteId)selectedExpeditionSiteId=target.siteId;
 if(target.recordId){publicRecordId=target.recordId;publicPackId='';publicSearch='';}
 if(target.roomId&&state.headquartersView.catalogue[target.roomId]){roomContext=target.roomId;selectedHqRoom=target.roomId;}
 setView(target.view,{resetBestiary:false,resetMagicReference:false});
 if(target.threadId)focusThread(target.threadId);
 if(target.almanacId){const scene=document.getElementById?.('almanac-'+target.almanacId.replaceAll(':','-'));scene?.scrollIntoView?.({block:'start'});scene?.focus?.({preventScroll:true});}
