function wardrobePage() {
 const entries=Object.entries(state.outfitProgressionView||{});
 const button=(who,tier,action,label,disabled=false,reasons=[])=>`<button data-outfit-action="${action}" data-outfit-owner="${escapeHtml(who)}" data-outfit-tier="${tier||''}" ${disabledAttrs(!disabled,reasons)}>${label}</button>`;
 return heading('GROWING CLOSER','Companion wardrobes','Shared memories lead to personal invitations. Choose an unlocked look whenever you are home together.','NO PHASE COST')+`<section class="panel"><p>Relaxed: remember one shared scene. Daring: remember three different scenes, including a new one after accepting the relaxed invitation. Replaying a scene does not count again.</p><div class="room-actions"><button data-view="householdChapters">Personal connections →</button><button data-view="livingStories">Resident conversations →</button><button data-view="stories">Personal stories →</button><button data-view="householdContent">Shared household moments →</button></div></section>`+
 (entries.length?entries.map(([who,r])=>`<section class="panel"><h2>${escapeHtml(r.name)}</h2><div class="portrait-layout"><div class="wardrobe-portrait"><img src="${assetUrl(residentPortraitId(who))}" alt="${escapeHtml(r.name)} in her current outfit"></div><div><p>${r.memories} remembered moment${r.memories===1?'':'s'} together.</p>${button(who,null,'choose-outfit','Return to original wardrobe',!r.canChange||!r.selected,[!r.canChange?'Return home together to change outfits.':'The original wardrobe is already selected.'])}${r.looks.map(look=>`<section class="panel outfit-step"><img class="outfit-preview" src="${assetUrl(look.id)}" alt="${escapeHtml(r.name+' — '+look.name)}" loading="lazy"><h3>${look.tier==='2'?'Relaxed':'Daring'} · ${escapeHtml(look.name)}</h3><p>${escapeHtml(look.description)}</p>${look.unlocked?`${look.memory.opening?`<blockquote>${escapeHtml(look.memory.opening)}</blockquote>`:''}<p>${escapeHtml(look.memory.response)}</p>${button(who,look.tier,'choose-outfit',r.selected===look.tier?'Currently wearing':'Wear this outfit',!r.canChange||r.selected===look.tier,[!r.canChange?'Return home together to change outfits.':'This outfit is already selected.'])}`:`<p>${escapeHtml(look.invitation)}</p><label for="outfit-response-${who}-${look.tier}">Your response</label><select id="outfit-response-${who}-${look.tier}">${Object.entries(look.responses).map(([key,label])=>`<option value="${key}">${escapeHtml(label)}</option>`).join('')}</select>${look.blockers.length?`<p class="muted">${look.blockers.map(escapeHtml).join(' ')}</p>`:''}${button(who,look.tier,'accept-outfit-invitation','Share this invitation',!look.canInvite,look.blockers)}`}</section>`).join('')}</div></div></section>`).join(''):'<section class="panel"><p>Invite a companion to live at the castle to discover her wardrobe journey.</p><button data-view="localEncounters">Meet the neighbours →</button></section>')+
 (state.characterCatalog.mira?`<details><summary>Mira’s original clothing & saved styles</summary>${embeddedSection(legacyWardrobePage())}</details>`:'');
}

function navigationIcon(id,fallback){const names={castle:'home',phaseTasks:'phase',estateHub:'estate',studyHub:'workshop',peopleHub:'people',household:'people',worldHub:'expeditions',expeditions:'expeditions',journal:'journal',storyJournal:'journal',magicHub:'magic',settings:'settings'};const asset=names[id]&&'nav-'+names[id];return asset&&state.originalAssets[asset]?`<img class="navigation-art" src="${assetUrl(asset)}" alt="" aria-hidden="true">`:paintedIcon(fallback,'nav');}

