 const pref=v.preferences[who];
 const card=r=>`<article class="panel"><h3>${escapeHtml(r.title)}</h3>${r.memory?`<p>${escapeHtml(r.memory.opening)}</p><p>You: ${escapeHtml(r.memory.playerLine)}</p><blockquote>${escapeHtml(r.memory.response)}</blockquote><small>Remembered on day ${r.memory.dayNumber}. Rereading changes nothing.</small>`:`<p>${escapeHtml(r.opening)}</p>${r.blockers.map(b=>`<p class="muted">${escapeHtml(b)}</p>`).join('')}${r.deferred?`<button data-relationship-action="restore-relationship" data-relationship-scene="${r.id}">Return this invitation</button>`:`<div class="social-response-list">${Object.entries(r.choices).map(([k,c])=>`<button data-relationship-action="share-relationship" data-relationship-scene="${r.id}" data-relationship-choice="${k}">${escapeHtml(c.label)}<small>${escapeHtml(c.effect)}</small></button>`).join('')}</div>${r.available?`<button data-relationship-action="defer-relationship" data-relationship-scene="${r.id}">Later</button>`:''}`}`}</article>`;
