 return `<nav class="ui-breadcrumb" aria-label="Breadcrumb"><button data-view="${section[0]}">${escapeHtml(section[2])}</button>${roomName&&!['room','hqRoom'].includes(currentView)?`<span aria-hidden="true">/</span><button data-hq-room="${escapeHtml(room)}">${escapeHtml(roomName)}</button>`:''}<span aria-hidden="true">/</span><span aria-current="page">${escapeHtml(label||'Room')}</span></nav>`;
