 const rows=[...magicRows,...guideRows,...UI_PRIMARY.map(([view,,label])=>({label,detail:view==='castle'?'Chapter 1 · The First Hearth · Home and castle':'Main destination',target:{view}})),...Object.values(SYSTEM_GROUPS).flatMap(g=>g.views.map(([view,label,detail])=>({label,detail,target:{view}}))),...UI_EXTRA_ROUTES.map(([view,label])=>({label,detail:view==='armsOfOurOwn'?'Chapter 5 · equipment, enchanting and the watch road':'Tools and collections',target:{view}})),...(state.soloLifeView.arrival?[{label:'Your arrival',detail:'Opening memories',target:{view:'arrival'}}]:[]),...Object.entries(state.headquartersView.catalogue).map(([roomId,room])=>({label:room.name,detail:'Room · '+room.group+' · '+room.use,target:{view:'hqRoom',roomId}})),...Object.entries(state.characterCatalog).map(([who,p])=>({label:p.name,detail:'Character · '+(p.role||'household'),target:{view:'characterProfile',personId:who}}))];
 return rows.filter((r,i)=>rows.findIndex(x=>JSON.stringify(x.target)===JSON.stringify(r.target))===i);
