function activityEntries(){
 const rows=[];const add=(id,kind,title,detail,target,people=[])=>rows.push({id,kind,title,detail,target,people});
 for(const r of state.sharedHistoryView||[])if(!r.memory&&!r.deferred&&!r.blockers.length)add('followup:'+r.id,'invitations',r.title,r.detail,{view:'sharedHistory'},r.people);
 for(const t of state.phaseTasks.tasks.filter(t=>!t.dismissed))add('phase:'+t.id,t.group==='choice'?'decisions':t.group==='invitation'?'invitations':'work',t.title,t.detail,{view:t.view||'phaseTasks',personId:t.personId||undefined},t.personId?[t.personId]:[]);
 for(const p of state.householdChaptersView?.people||[]){const next=p.personal.find(r=>r.available&&!r.memory);if(next)add('chapter:'+next.id,'invitations',next.title,'A personal conversation. No phase cost.',{view:'householdChapters',chapterPerson:p.id},[p.id]);}
 for(const r of state.socialLifeView?.scenes||[])if(r.available&&!r.deferred&&!r.memory)add('social:'+r.id,'invitations',r.title,'A conversation with room for your response.',{view:'characterProfile',personId:r.participants.find(w=>w!=='founder')||'founder',characterTab:'talk',sceneId:r.id},r.participants);
 for(const r of state.relationshipsView?.scenes||[])if(r.available&&!r.deferred&&!r.memory)add('bond:'+r.id,'invitations',r.title,'Shared relationships and agreements.',{view:'characterProfile',personId:r.participants.find(w=>w!=='founder')||'founder',characterTab:'relationships'},r.participants);
 for(const [who,p] of Object.entries(state.romanceView||{}))for(const r of p.scenes)if(r.available&&!r.deferred&&!r.memory)add('romance:'+r.id,'invitations',r.title,'A personal invitation. Available whenever you choose.',{view:'characterProfile',personId:who,characterTab:'relationships'},[who]);
 for(const [who,p] of Object.entries(state.romanceView||{})){const c=p.closeness;if(!c||c.deferred||c.mode!=='open'||c.pending)continue;const r=c.stages.find(x=>x.milestone.available)||c.stages.find(x=>x.moment.available&&!x.moment.count);if(r){const d=r.milestone.available?r.milestone:r.moment;add('closeness:'+who,'invitations',d.title,'An optional moment together. No deadline or automatic progression.',{view:'characterProfile',personId:who,characterTab:'relationships',closenessStage:r.stage},[who]);}}
 for(const r of state.householdSagasView?.stories||[])if(r.stage<3&&!r.deferred&&!r.blockers.length)add('saga:'+r.id,'invitations',r.title,'Shared household story · '+r.stage+'/3 scenes remembered.',{view:'householdSagas',sagaId:r.id},r.cast);
 for(const q of state.characterQuestsView?.quests||[])if(q.status!=='complete'&&q.status!=='declined'&&!q.blockers.length)add('quest:'+q.id,q.status==='offered'?'invitations':'work',q.title,q.status==='offered'?'A request to consider. Nothing expires.':'Personal quest · '+q.status,{view:'characterProfile',personId:q.who,characterTab:'quests',questId:q.id},[q.who]);
 for(const r of state.companionParticipationView?.events||[])if(!r.memory&&!r.deferred&&!r.blockers.length)add('participation:'+r.id,'invitations',r.title,'A conversation after shared work.',{view:'characterProfile',personId:r.who,characterTab:'talk'},[r.who]);
 for(const [site,d] of Object.entries(state.partyJourneysView?.sites||{}))for(const r of d.scenes)if(r.available)add('journey:'+site+':'+r.id,'invitations',r.title,d.name+' · optional conversation.',{view:'expeditions',siteId:site},r.participants);
 for(const r of state.companionAlmanacView?.scenes||[])if(r.available)add('almanac:'+r.id,'invitations',r.title,'An optional conversation. No time or supplies are spent.',almanacTarget(r),r.participants.filter(w=>w!=='founder'));
 for(const r of state.companionThreadsView?.scenes||[])if(r.available)add('thread:'+r.id,'invitations',r.title,(r.turn?'Continue · ':'')+'Exchange '+(r.turn+1)+' of '+r.totalTurns+'. Your responses are saved. No time or supplies.',threadTarget(r),r.participants.slice(1));

 const rank={decisions:0,work:1,invitations:2};return rows.sort((a,b)=>rank[a.kind]-rank[b.kind]);
}
