 for(const [id,n] of Object.entries(state.craftedArtifacts||{}))if(n>0&&state.recipeCatalog[id])add('artifact:'+id,'artifacts',state.recipeCatalog[id].name,'owned',n+' owned · review its recipe and uses',[],{view:'fullWorkshop',recipeId:id});
