 for(const r of state.socialLifeView?.scenes||[])memory('social:'+r.id,r.memory,{view:'characterProfile',personId:r.participants.find(w=>w!=='founder')||'founder',characterTab:'talk',sceneId:r.id});
 for(const r of state.relationshipsView?.scenes||[])memory('bond:'+r.id,r.memory,{view:'characterProfile',personId:r.participants.find(w=>w!=='founder')||'founder',characterTab:'relationships'});
 for(const [who,p] of Object.entries(state.romanceView||{}))for(const r of [...p.scenes,...p.dates])memory('romance:'+who+':'+(r.id||'date:'+r.roomId),r.memory,{view:'characterProfile',personId:who,characterTab:'relationships'});
 for(const [who,p] of Object.entries(state.romanceView||{}))for(const row of p.closeness?.stages||[])for(const kind of ['moment','milestone'])memory('close:'+who+':'+row.stage+':'+kind,row[kind].memory,{view:'characterProfile',personId:who,characterTab:'relationships'});
