const intimacyStage={};
function intimacyPanel(who){
 const p=state.romanceView?.[who]?.closeness;if(!p)return '';
 const e=escapeHtml,button=(type,label,extra={},blocked=[])=>`<button data-intimacy-action="${e(JSON.stringify({type,characterId:who,...extra}))}" ${disabledAttrs(!blocked.length,blocked)}>${e(label)}</button>`;
 const index=intimacyStage[who]??Math.min(p.completed,3),row=p.stages[index]||p.stages[0];
 const memory=m=>`<article class="closeness-memory"><h4>${e(m.title)}</h4><p>${e(m.opening)}</p><blockquote>${e(m.response)}</blockquote><small>Day ${m.dayNumber} · ${e(m.phase)}. Rereading changes nothing.</small></article>`;
 const reasons=rs=>rs.length?`<p class="ui-requirement">${e(rs[0])}</p>${rs.length>1?`<details><summary>All requirements (${rs.length})</summary><ul>${rs.map(r=>`<li>${e(r)}</li>`).join('')}</ul></details>`:''}`:'';
 let body='';
 if(p.pending){
  const d=p.pending;
  body=`<article class="closeness-reader" aria-label="Open closeness invitation"><img class="closeness-room" src="${e(assetUrl(d.roomId))}" alt="${e(state.rooms[d.roomId]?.name||state.headquartersView.catalogue[d.roomId]?.name||'A quiet place together')}"><h3>${e(d.title)}</h3><p>${e(d.opening)}</p><p>Choose what feels right now. Quiet company leaves this scene available; you can also leave and return later.</p>${reasons(d.blockers)}<div class="closeness-actions">${button('intimacy-resolve','Accept the affectionate invitation',{choice:'close'},d.blockers)}${button('intimacy-resolve','Choose quiet company instead',{choice:'quiet'},d.blockers)}${button('intimacy-resolve','Leave this for another time',{choice:'leave'})}</div></article>`;
 }else if(p.mode!=='open')body='<p>These invitations are paused with your romantic relationship. Your memories remain below.</p>';
 else if(p.deferred)body=`<p>You put these invitations aside. They have no deadline.</p>${button('intimacy-restore','Return these invitations')}`;
 else body=`<nav class="closeness-stages" aria-label="Closeness stages">${p.stages.map(r=>`<button data-intimacy-stage="${r.stage}" aria-pressed="${r.stage===row.stage}"><span>${r.stage+1}. ${e(r.label)}</span><small>${r.milestone.memory?'Milestone remembered':r.moment.count?'A moment shared':'To discover'}</small></button>`).join('')}</nav><article class="closeness-choice"><h3>${e(row.label)}</h3><div class="closeness-options"><section><h4>${e(row.moment.title)}</h4><p>Repeatable${row.moment.count?' · shared '+row.moment.count+' time'+(row.moment.count===1?'':'s'):''}</p>${reasons(row.moment.blockers)}${button('intimacy-begin',row.moment.count?'Share this moment again':'Read the invitation',{stage:row.stage,sceneKind:'moment'},row.moment.blockers)}</section><section><h4>${e(row.milestone.title)}</h4><p>One-time relationship scene</p>${row.milestone.memory?'<p>Remembered. Read it again below whenever you like.</p>':reasons(row.milestone.blockers)+button('intimacy-begin','Read the milestone invitation',{stage:row.stage,sceneKind:'milestone'},row.milestone.blockers)}</section></div></article>${button('intimacy-defer','Put these invitations aside')}`;
 const memories=p.stages.flatMap(r=>[r.moment.memory,r.milestone.memory]).filter(Boolean);
 return `<section class="panel closeness-panel" data-ui-key="closeness:${who}"><h2>Time together</h2><p>Four stages · ${p.completed}/4 milestones remembered. Read an invitation and choose how to respond.</p>${body}${p.latest?`<section class="closeness-latest" aria-label="Last shared scene"><h3>${e(p.latest.title)}</h3><blockquote>${e(p.latest.response)}</blockquote><small>Day ${p.latest.dayNumber} · ${e(p.latest.phase)}${p.latest.choice==='quiet'?' · Quiet company; milestone still available':''}</small></section>`:''}<details><summary>Scene requirements and effects</summary><p>These scenes follow mutual attraction, dating, partnership and deep partnership. Complete the repeatable scene at a stage before its one-time relationship scene. One affectionate scene per companion per phase; later endings wait until a new day after the previous milestone.</p><p>No crowns, materials, relationship points or training rewards are awarded. Choosing quiet company, leaving or putting an invitation aside removes no progress. Only Advance moves time. Private evenings require Rest for both of you and a bedroom assigned only to either or both of you; the scene does not replace overnight rest.</p><button data-view="workArrangements">Review assignments →</button><button data-view="housing">Review bedrooms →</button></details>${memories.length?`<details><summary>Shared memories · ${memories.length}</summary>${memories.map(memory).join('')}</details>`:''}</section>`;
}

