 return `<section class="panel" data-ui-key="patrol-homecoming"><p class="eyebrow">HOME FROM THE PATROL</p><h2>${escapeHtml(v.name)} · ${v.complete?'completed':'returned early'}</h2><p>${v.loot.crowns} crowns · ${v.loot.food} provisions${Object.keys(v.loot.materials).length?' · '+Object.entries(v.loot.materials).map(([k,n])=>n+' '+escapeHtml(state.materialCatalog[k]?.name||k)).join(', '):''}</p><div class="patrol-recovery">${v.rows.map(w=>`<article>${portraitImage(w.id)}<strong>${escapeHtml(w.name)} · ${w.vitality}/6</strong><p>${!w.atHome?'Away again':w.resting?'Resting':'Assigned other work'}${w.needsSleep?' · no night at home since this return':''}</p>${w.vitality<6?`<small>Ordinary rest: at least ${w.dayHealing} by day; up to ${w.nightHealing} overnight, before personal or sanctuary bonuses.</small>`:''}<small>${Object.entries(w.roles).filter(([k,n])=>n>0&&k!=='actions').map(([k,n])=>escapeHtml({damage:'Damage dealt',healed:'Vitality restored',protected:'Damage diverted',controlled:'Attacks disrupted'}[k]||k)+': '+n).join(' · ')}</small><button data-ui-target="${escapeHtml(JSON.stringify({view:'characterProfile',personId:w.id,characterTab:'talk'}))}">Visit ${escapeHtml(w.name)} →</button></article>`).join('')}</div>${v.unlocks.map(u=>`<p>${portraitImage(u.who)} ${escapeHtml(state.characterCatalog[u.who]?.name||u.who)}: ${escapeHtml(u.name)} earned a rank-${u.rank} refinement. <button data-personal-armoury="${escapeHtml(u.who)}">Review signature equipment →</button></p>`).join('')}<div class="room-actions">${foodButton({type:'watch-rest-party',reportId:v.reportId},'Set this returning party to Rest',v.blockers)}${!v.mission?`<button data-patrol-repeat="${v.reportId}">Prepare this party again →</button>`:'<button data-view="armsOfOurOwn">Continue Chapter 5 →</button>'}${!always?foodButton({type:'watch-dismiss-return',reportId:v.reportId},'Dismiss this card'):''}</div><small>Preparing a repeat opens party review. It never departs automatically. Rest takes effect on Advance; arrival does not count as sleep.</small></section>`;
